class WordDictionary {
  private root: TrieNode;

  constructor() {
    // Initialize the root of the Trie.
    this.root = new TrieNode();
  }

  addWord(word: string): void {
    // Start from the root of the Trie.
    let cur = this.root;

    // Iterate through each character of the word.
    for (const c of word) {
      // If the current node doesn't have a child for the current character,
      if (!cur.children.has(c)) {
        // create a new TrieNode for it.
        cur.children.set(c, new TrieNode());
      }
      // Move to the next node, which corresponds to the current character.
      cur = cur.children.get(c)!;
    }

    // Mark the last node as the end of a word.
    cur.isWord = true;
  }

  search(word: string): boolean {
    // Define a recursive Depth-First Search (DFS) function.
    const dfs = (j: number, node: TrieNode): boolean => {
      // Start searching from the given node.
      let cur = node;

      // Iterate through the remaining characters of the word.
      for (let i = j; i < word.length; i++) {
        const c = word[i];

        // wildcard case: If the character is a wildcard ('.').
        if (c === ".") {
          // Iterate through all the children of the current node.
          for (const child of cur.children.values()) {
            // Recursively call DFS on each child, advancing the index.
            if (dfs(i + 1, child)) {
              // If any of the children leads to a match, return true.
              return true;
            }
          }
          // If none of the children leads to a match, return false.
          return false;
        } else {
          // If the character is not a wildcard.
          // and if the current node does not have that character as a child,
          if (!cur.children.has(c)) {
            // then the word doesn't exist, return false.
            return false;
          }
          // Otherwise, move to the next node corresponding to the current character.
          cur = cur.children.get(c)!;
        }
      }

      // If we've reached the end of the word, return true if the current node is a word.
      return cur.isWord;
    };

    // Start the DFS from the root of the Trie.
    return dfs(0, this.root);
  }
}

