    def __init__(self):
        # Initialize the root of the Trie
        self.root = TrieNode()

    def addWord(self, word: str) -> None:
        # Start from the root of the Trie
        node = self.root
        # Iterate through each character in the word
        for char in word:
            # If the character is not a child of the current node,
            # create a new TrieNode for it
            if char not in node.children:
                node.children[char] = TrieNode()
            # Move to the next node (child node)
            node = node.children[char]
        # Mark the last node as the end of a word
        node.is_word = True

    def search(self, word: str) -> bool:
        # Define a recursive Depth-First Search (DFS) function
        def dfs(node, index):
            # If the index reaches the end of the word,
            # return whether the current node represents the end of a word
            if index == len(word):
                return node.is_word

            # Get the character at the current index
            char = word[index]
            # If the character is a wildcard ('.')
            if char == '.':
                # Iterate through all children of the current node
                for child in node.children.values():
                    # Recursively call DFS on each child
                    if dfs(child, index + 1):
                        # If any of the recursive calls return True,
                        # the search is successful
                        return True
                # If none of the children lead to a successful search,
                # return False
                return False
            # If the character is not a wildcard
            else:
                # If the character is not a child of the current node,
                # the search fails
                if char not in node.children:
                    return False
                # Recursively call DFS on the corresponding child node
                return dfs(node.children[char], index + 1)

        # Start the search from the root node and the beginning of the word
        return dfs(self.root, 0)

public static class WordDictionary {
    private TrieNode root;

    public Solution() {
        // Initialize the root of the Trie.
        root = new TrieNode();
    }

    public void addWord(String word) {
        // Adds a word to the Trie.
        TrieNode current = root;
        // Iterate through each character in the word.
        for (char ch : word.toCharArray()) {
            // If the current character is not a child of the current node, create a new TrieNode.
            if (!current.children.containsKey(ch)) {
                current.children.put(ch, new TrieNode());
            }
            // Move to the next node in the Trie.
            current = current.children.get(ch);
        }
        // Mark the last node as the end of a word.
        current.isWord = true;
    }

    public boolean search(String word) {
        // Searches for a word in the Trie.
        return searchHelper(word, 0, root);
    }

    private boolean searchHelper(String word, int index, TrieNode node) {
        // Recursive helper function to search for a word in the Trie.
        // Base case: if the index is equal to the length of the word, return whether the current node is the end of a word.
        if (index == word.length()) {
            return node.isWord;
        }

        char ch = word.charAt(index);

        // If the current character is a wildcard ('.').
        if (ch == '.') {
            // Iterate through all children of the current node.
            for (TrieNode child : node.children.values()) {
                // Recursively call searchHelper with the next index and the child node.
                if (searchHelper(word, index + 1, child)) {
                    // If any of the recursive calls return true, return true.
                    return true;
                }
            }
            // If none of the recursive calls return true, return false.
            return false;
        } else {
            // If the current character is not a wildcard.
            // If the current character is not a child of the current node, return false.
            if (!node.children.containsKey(ch)) {
                return false;
            }
            // Recursively call searchHelper with the next index and the child node.
            return searchHelper(word, index + 1, node.children.get(ch));
        }
    }
}

