class Solution {
public:
    struct TrieNode {
        bool isEnd = false; // Flag to mark the end of a word
        unordered_map<char, TrieNode*> children; // Map to store children nodes for each character
    };

    WordDictionary() {
        root = new TrieNode(); // Initialize the root node of the Trie
    }

    void addWord(string word) {
        TrieNode* node = root; // Start from the root node
        for (char c : word) {
            // Iterate through each character in the word
            if (node->children.find(c) == node->children.end()) {
                // If the character is not present in the children, create a new TrieNode
                node->children[c] = new TrieNode();
            }
            node = node->children[c]; // Move to the next node corresponding to the character
        }
        node->isEnd = true; // Mark the last node as the end of the word
    }

    bool search(string word) {
        return dfs(root, word, 0); // Start DFS from the root node and index 0 of the word
    }

private:
    TrieNode* root; // Root of the Trie

    // Depth-First Search function to find the word
    bool dfs(TrieNode* node, const string& word, int i) {
        // Base case: If we have reached the end of the word
        if (i == word.length()) {
            return node->isEnd; // Return true if the current node is the end of a word, otherwise false
        }

        char c = word[i]; // Current character to search for

        // If the character is a wildcard '.'
        if (c == '.') {
            // Iterate through all children of the current node
            for (auto& [ch, child] : node->children) {
                // Recursively call DFS for each child
                if (dfs(child, word, i + 1)) {
                    // If any child returns true, the word is found
                    return true;
                }
            }
            // If none of the children lead to a match, return false
            return false;
        } else {
            // If the character is not a wildcard
            if (node->children.find(c) == node->children.end()) {
                // If the character is not present in the children, the word doesn't exist
                return false;
            }
            // Recursively call DFS for the corresponding child
            return dfs(node->children[c], word, i + 1);
        }
    }
};

