function spiralOrder(matrix: number[][]): number[] {
    // Result array to store the elements in spiral order
    const res: number[] = [];

    // Initialize boundaries for the spiral traversal
    let left: number = 0; // Left boundary index
    let right: number = matrix[0].length; // Right boundary index
    let top: number = 0; // Top boundary index
    let bottom: number = matrix.length; // Bottom boundary index

    // Continue traversal as long as the boundaries haven't crossed
    while (left < right && top < bottom) {
        // Traverse from left to right on the top row
        for (let i = left; i < right; i++) {
            res.push(matrix[top][i]); // Add element to result array
        }
        top += 1; // Move the top boundary down

        // Traverse from top to bottom on the right column
        for (let i = top; i < bottom; i++) {
            res.push(matrix[i][right - 1]); // Add element to result array
        }
        right -= 1; // Move the right boundary left

        // Check if boundaries have crossed to avoid duplicate traversal
        if (!(left < right && top < bottom)) {
            break; // Exit loop if boundaries have crossed
        }

        // Traverse from right to left on the bottom row
        for (let i = right - 1; i >= left; i--) {
            res.push(matrix[bottom - 1][i]); // Add element to result array
        }
        bottom -= 1; // Move the bottom boundary up

        // Traverse from bottom to top on the left column
        for (let i = bottom - 1; i >= top; i--) {
            res.push(matrix[i][left]); // Add element to result array
        }
        left += 1; // Move the left boundary right
    }

    return res; // Return the result array
}

