        int left = 0;                       // Left boundary.
        int right = matrix[0].size();        // Right boundary (exclusive).
        int top = 0;                        // Top boundary.
        int bottom = matrix.size();         // Bottom boundary (exclusive).

        // Continue traversing as long as the boundaries haven't crossed.
        while (left < right && top < bottom) {
            // Traverse from left to right along the top row.
            for (int i = left; i < right; i++) {
                res.push_back(matrix[top][i]);
            }
            // Move the top boundary down by one row.
            top += 1;

            // Traverse from top to bottom along the right column.
            for (int i = top; i < bottom; i++) {
                res.push_back(matrix[i][right - 1]);
            }
            // Move the right boundary left by one column.
            right -= 1;

            // Check if the boundaries have crossed to avoid duplicate traversal.
            if (!(left < right && top < bottom)) {
                break;
            }

            // Traverse from right to left along the bottom row.
            for (int i = right - 1; i >= left; i--) {
                res.push_back(matrix[bottom - 1][i]);
            }
            // Move the bottom boundary up by one row.
            bottom -= 1;

            // Traverse from bottom to top along the left column.
            for (int i = bottom - 1; i >= top; i--) {
                res.push_back(matrix[i][left]);
            }
            // Move the left boundary right by one column.
            left += 1;
        }

        // Return the result vector containing the spiral order elements.
        return res;
    }
