function mergeTriplets(triplets: number[][], target: number[]): boolean {
    const good = new Set<number>();

    for (const t of triplets) {
        // If any component of the current triplet `t` is greater than the corresponding
        // component in `target`, this triplet cannot be used.
        // The `max` operation would always result in a value greater than `target[i]`,
        // making it impossible to form `target`.
        if (
            t[0] > target[0] ||
            t[1] > target[1] ||
            t[2] > target[2]
        ) {
            continue; // Skip this triplet
        }

        // If the triplet `t` passes the filter (all its components are <= target's components),
        // check if any of its components exactly match the target's components.
        // If it does, it means this triplet *could* contribute to forming that specific
        // component of the target triplet.
        t.forEach((v, i) => {
            if (v === target[i]) {
                good.add(i); // Mark this component index as "achievable"
            }
        });
    }

    // If we have found a way to achieve all three components (index 0, 1, and 2)
    // of the target triplet using valid triplets, then it's possible.
    return good.size === 3;
}

