function dailyTemperatures(temperatures: number[]): number[] {
    // Initialize the result array `res` with the same length as `temperatures`.
    // Each element is set to 0 initially. A 0 indicates that no warmer temperature
    // was found in the future for that particular day.
    const res = new Array(temperatures.length).fill(0);

    // Initialize an empty stack. This stack will store pairs of `[temperature, index]`.
    // It will maintain a *monotonic decreasing* sequence of temperatures from bottom to top.
    // This means that `stack[k][0] >= stack[k+1][0]` will generally hold.
    const stack: [number, number][] = []; // Stores [temperature, index]

    // Iterate through the `temperatures` array from left to right, processing each day.
    for (let i = 0; i < temperatures.length; i++) {
        // Get the current day's temperature.
        const t = temperatures[i];

        // This `while` loop is the core of the monotonic stack logic.
        // It checks two conditions:
        // 1. `stack.length`: Ensures there are elements in the stack to compare against.
        // 2. `t > stack[stack.length - 1][0]`: Checks if the current temperature `t` is
        //    strictly warmer than the temperature at the top of the stack.
        //    If `t` is warmer, it means we've found the *first* future warmer day for
        //    the temperature at the stack's top.
        while (stack.length && t > stack[stack.length - 1][0]) {
            // If the conditions are met, pop the top element from the stack.
            // We use destructuring to get the `stackInd` (the index of the popped temperature)
            // and ignore the temperature itself, as we already know it's cooler than `t`.
            const [, stackInd] = stack.pop()!;

            // Calculate the number of days to wait for a warmer temperature.
            // This is the difference between the current day's index (`i`)
            // and the index of the day that was just popped (`stackInd`).
            res[stackInd] = i - stackInd;
        }

        // After processing the `while` loop (which empties the stack of all temperatures
        // that are cooler than or equal to `t`), push the current temperature `t`
        // and its index `i` onto the stack.
        // This maintains the monotonic decreasing property: `t` will either be pushed
        // on top of a larger temperature (maintaining decreasing order), or it will be
        // the new smallest temperature if all previous ones were popped because they
        // were smaller than `t`.
        stack.push([t, i]);
    }

    // After iterating through all temperatures, the `res` array contains the
    // waiting days for each corresponding temperature. Days for which no warmer
    // temperature was found will retain their initial value of 0.
    return res;
}

