    }

    // Sort the max heap in descending order to simulate max heap behavior.
    maxHeap.sort((a, b) => b - a);

    // Initialize the time counter.
    let time = 0;

    // Create a queue to store the tasks that are in the cooling period.
    // Each element in the queue is a tuple: [remainingCount, availableTime].
    const queue: [number, number][] = [];

    // Iterate while there are tasks in the max heap or the queue.
    while (maxHeap.length > 0 || queue.length > 0) {       // Increment the time.
        time++;

        // If there are tasks in the max heap, process the task with the highest frequency.
        if (maxHeap.length > 0) {
            // Get the highest frequency task from the max heap and decrement its count.
            const cnt = maxHeap.shift()! - 1;

            // If the count is still greater than 0, add it to the cooling queue with its available time.
            if (cnt > 0) {
                queue.push([cnt, time + n]);
