        }

        // If there are tasks in the cooling queue whose available time is equal to the current time,
        // re-add them to the max heap.
        if (queue.length > 0 && queue[0][1] === time) {
            // Get the task from the front of the queue.
            const [cnt] = queue.shift()!;

            // Add the task back to the max heap.
            maxHeap.push(cnt);

            // Sort the max heap again to maintain the max heap property.
            maxHeap.sort((a, b) => b - a);
        }
    }

    // Return the total time.
    return time;
}

