    if (nums.length === 0) return 0;

    // maxProduct: This variable will store the overall maximum product found so far. Initialize it with the first element of the array.
    let maxProduct = nums[0];

    // currentMax: This variable tracks the maximum product ending at the current index 'i'.
    // It is initialized with the first element of the array.
    let currentMax = nums[0];

    // currentMin: This variable tracks the minimum product ending at the current index 'i'.
    // It is initialized with the first element of the array.
    // Note: We need to track the minimum because multiplying a negative number with the current minimum can result in a new maximum.
    let currentMin = nums[0];

    // Iterate through the array starting from the second element (index 1).
    for (let i = 1; i < nums.length; i++) {
        const num = nums[i];

        // Store the current maximum product in a temporary variable 'tempMax'.
        // This is necessary because we'll update 'currentMax' and need the original value for updating 'currentMin'.
        const tempMax = currentMax;

        // Update 'currentMax' by considering three possibilities:
        // 1. The current number itself (start a new subarray).
        // 2. The current number multiplied by the previous 'currentMax' (extend the previous maximum subarray).
        // 3. The current number multiplied by the previous 'currentMin' (if the current number is negative, multiplying it with the minimum could give a new maximum).
        currentMax = Math.max(
            num,
            num * currentMax,
            num * currentMin
        );

        // Update 'currentMin' similarly by considering three possibilities:
        // 1. The current number itself (start a new subarray).
        // 2. The current number multiplied by the previous 'tempMax' (extend the previous maximum subarray).
        // 3. The current number multiplied by the previous 'currentMin' (if the current number is positive, multiplying it with the minimum could give a new minimum).
        currentMin = Math.min(
            num,
            num * tempMax,
            num * currentMin
        );

        // Update the overall 'maxProduct' by comparing it with the current maximum product.
        maxProduct = Math.max(maxProduct, currentMax);
    }

    // After iterating through the entire array, 'maxProduct' will contain the maximum product of any subarray. Return it.
    return maxProduct;
