function subsetsWithDup(nums: number[]): number[][] {
    // Result array to store all the subsets
    const res: number[][] = [];

    // Sort the input array to handle duplicates efficiently
    nums.sort((a, b) => a - b);

    // Backtracking function to generate subsets
    function backtrack(i: number, subset: number[]) {
        // Add a copy of the current subset to the result
        res.push([...subset]);

        // Iterate through the remaining elements in the input array
        for (let j = i; j < nums.length; j++) {
            // Skip duplicate elements to avoid duplicate subsets
            // This condition checks if the current element is the same as the previous element
            // and if it's not the first element in the current level of recursion.
            if (j > i && nums[j] === nums[j - 1]) {
                continue; // Skip duplicate elements in the same level
            }

            // Include the current element in the subset
            subset.push(nums[j]);

            // Recursively call the backtrack function with the next index
            backtrack(j + 1, subset);

            // Backtrack: remove the current element from the subset to explore other possibilities
            subset.pop();
        }
    }

    // Start the backtracking process from the beginning of the array with an empty subset
    backtrack(0, []);

    // Return the result array containing all unique subsets
    return res;
}

