function findRedundantConnection(edges: number[][]): number[] {
    const n = edges.length;

    // Initialize parent array for DSU. Each node is initially its own parent.
    // Nodes are 1-indexed, so array size is n + 1.
    const parent: number[] = Array.from({ length: n + 1 }, (_, i) => i);
    // Initialize rank array for union by rank optimization.
    // Rank represents the approximate height or size of the tree.
    const rank: number[] = Array(n + 1).fill(1);

    /**
     * Finds the representative (root) of the set containing 'node'.
     * Uses path compression to flatten the tree structure during traversal.
     * @param node The node to find the root for.
     * @returns The root of the set 'node' belongs to.
     */
    function find(node: number): number {
        // If the node is not its own parent, it's not the root.
        // Recursively find the root and compress the path.
        if (node !== parent[node]) {
            parent[node] = find(parent[node]); // Path compression
        }
        return parent[node];
    }

    /**
     * Merges the sets containing n1 and n2.
     * Uses union by rank to keep the tree shallow.
     * @param n1 One node.
     * @param n2 Another node.
     * @returns True if the union was successful (n1 and n2 were in different sets).
     *          False if n1 and n2 were already in the same set (cycle detected).
     */
    function union(n1: number, n2: number): boolean {
        // Find the roots of n1 and n2's sets.
        const p1 = find(n1);
        const p2 = find(n2);

        // If they already have the same root, they are connected.
        // Adding an edge between them would create a cycle.
        if (p1 === p2) {
            return false; // Cycle detected
        }

        // Union by rank: Attach the smaller rank tree under the root of the larger rank tree.
        // This helps maintain a balanced tree structure.
        if (rank[p1] > rank[p2]) {
            parent[p2] = p1;
            rank[p1] += rank[p2]; // Update the size/rank of the new root
        } else { // If rank[p2] >= rank[p1]
            parent[p1] = p2;
            rank[p2] += rank[p1]; // Update the size/rank of the new root
        }

        return true; // Union successful
    }

    // Iterate through each edge in the input array.
    // The first edge that causes a union to fail is the redundant one.
    for (const [u, v] of edges) {
        // Attempt to union the components containing u and v.
        // If union returns false, it means u and v were already connected,
        // and this edge [u, v] forms a cycle.
        if (!union(u, v)) {
            return [u, v]; // This is the redundant connection.
        }
    }

    // According to problem constraints, a redundant edge is guaranteed to be found.
    // This line should technically not be reached.
    return [];
}

