    private int[] size; // Using 'size' instead of 'rank' to reflect union-by-size behavior

       /**
     * Finds the redundant connection in a graph that started as a tree with one additional edge.
     * This approach uses the Disjoint Set Union (DSU) data structure.
     * We iterate through the edges; if an edge connects two nodes that are already in the same set,
     * it means this edge forms a cycle and is therefore the redundant connection.
     * Since we need the last such edge, the first one we encounter when iterating through input edges
     * sequentially will be the answer.
     *
     * @param edges An array of edges where edges[i] = [ai, bi] indicates an edge between nodes ai and bi.
     * @return The redundant edge that can be removed to restore the tree property.
     */
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length; // The number of nodes is equal to the number of edges (n nodes, n edges in a tree + 1 edge graph)

        // Initialize DSU structures. Nodes are 1-indexed, so arrays are of size n + 1.
        parent = new int[n + 1];
        size = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            parent[i] = i; // Each node is initially its own parent
            size[i] = 1;   // Each set initially contains one element
        }

        // Iterate through each edge in the input.
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];

            // Attempt to union the sets containing u and v.
            // If union returns false, it means u and v were already connected.
            // This implies adding the current edge [u, v] forms a cycle.
            if (!union(u, v)) {
                return edge; // This is the redundant connection.
            }
        }

        // According to the problem constraints, there will always be exactly one redundant edge,
        // so this line should theoretically not be reached.
        return new int[0];
    }

    /**
     * Finds the representative (root) of the set to which element 'i' belongs.
     * Implements path compression to flatten the tree structure during traversal,
     * making future find operations faster.
     *
     * @param i The element for which to find the root.
     * @return The root of the set containing 'i'.
     */
    private int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        parent[i] = find(parent[i]); // Path compression
        return parent[i];
    }

    /**
     * Unites the sets containing elements 'i' and 'j'.
     * Implements union by size to keep the trees balanced, improving performance.
     *
     * @param i One of the elements to unite.
     * @param j The other element to unite.
     * @return true if the union successfully merged two distinct sets (meaning no cycle was formed).
     *         false if 'i' and 'j' were already in the same set (meaning adding an edge between them creates a cycle).
     */
    private boolean union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI == rootJ) {
            return false; // i and j are already connected, adding an edge between them forms a cycle.
        }

        // Union by size: attach the smaller tree under the root of the larger tree.
        // This helps keep the overall tree height small.
        if (size[rootI] < size[rootJ]) {
            parent[rootI] = rootJ;
            size[rootJ] += size[rootI];
        } else {
            // If size[rootI] >= size[rootJ], attach rootJ under rootI.
            parent[rootJ] = rootI;
            size[rootI] += size[rootJ];
        }
        return true;
    }


}

