  if (!intervals || intervals.length === 0) {
    return 0;
  }

  // Sort the intervals based on their end times in ascending order.
  // This sorting strategy is crucial for the greedy approach.
  intervals.sort((a, b) => a[1] - b[1]);

  // Initialize the count of non-overlapping intervals to 1.
  // We start with 1 because the first interval is always considered non-overlapping initially.
  let nonOverlappingCount = 1;

  // Initialize the end time of the last non-overlapping interval to the end time of the first interval.
  // This variable will be updated as we iterate through the sorted intervals.
  let lastEndTime = intervals[0][1];

  // Iterate through the sorted intervals starting from the second interval (index 1).
  for (let i = 1; i < intervals.length; i++) {
    // Get the start and end times of the current interval.
    const currentStartTime = intervals[i][0];
    const currentEndTime = intervals[i][1];

    // Check if the current interval overlaps with the last non-overlapping interval.
    // An interval overlaps if its start time is less than the end time of the last non-overlapping interval.
    if (currentStartTime >= lastEndTime) {
      // If the current interval does not overlap, increment the count of non-overlapping intervals.
      nonOverlappingCount++;
      // Update the end time of the last non-overlapping interval to the end time of the current interval.
      lastEndTime = currentEndTime;
    }
  }

  // The minimum number of intervals to remove is the total number of intervals
  // minus the number of non-overlapping intervals.
  return intervals.length - nonOverlappingCount;
}

