function kClosest(points: number[][], k: number): number[][] {
    const minHeap: number[][] = [];

    // Custom comparison function for the min heap
    const compare = (a: number[], b: number[]): number => {
        return a[0] - b[0]; // Compare based on the first element (distance)
    };

    // Function to calculate the squared Euclidean distance from the origin (0, 0)
    const getDistance = (point: number[]): number => {
        return point[0] * point[0] + point[1] * point[1]; // Calculate x^2 + y^2
    };

    // Build the min heap
    for (const point of points) {
        const distance = getDistance(point); // Calculate the distance for the current point
        minHeap.push([distance, point[0], point[1]]); // Push the distance and the point's coordinates into the minHeap
        minHeap.sort(compare); // Sort the minHeap after each insertion to maintain the min-heap property (O(n log n) due to sorting)
    }

    const result: number[][] = [];
    for (let i = 0; i < k; i++) {
        const current = minHeap.shift(); // Remove the element with the smallest distance (the first element) - O(n)
        if (current) {
            result.push([current[1], current[2]]); // Extract the x and y coordinates and add them to the result array
        }
    }

    return result;
}

