function tarjanSCC(graph: number[][]): number[][] {
  // n represents the number of vertices in the graph
  const n = graph.length;
  // disc[i] stores the discovery time of vertex i
  const disc = Array(n).fill(-1);
  // low[i] stores the lowest discovery time reachable from vertex i
  const low = Array(n).fill(-1);
  // onStack[i] indicates whether vertex i is currently in the stack
  const onStack = Array(n).fill(false);
  // stack stores the vertices in the current DFS path
  const stack: number[] = [];
  // sccs stores the strongly connected components
  const sccs: number[][] = [];
  // time is a counter for discovery time
  let time = 0;

  // dfs function to perform depth-first search
  function dfs(u: number) {
    // Initialize discovery time and lowlink value for vertex u
    disc[u] = low[u] = time++;
    // Push vertex u onto the stack
    stack.push(u);
    // Mark vertex u as being on the stack
    onStack[u] = true;

    // Iterate through the neighbors of vertex u
    for (const v of graph[u]) {
      // If vertex v has not been visited
      if (disc[v] === -1) {
        // Recursively call DFS on vertex v
        dfs(v);
        // Update lowlink value of u based on the lowlink value of v
        low[u] = Math.min(low[u], low[v]);
      } else if (onStack[v]) {
        // If vertex v is on the stack (back edge)
        // Update lowlink value of u based on the discovery time of v
        low[u] = Math.min(low[u], disc[v]);
      }
    }

    // If the lowlink value of u equals its discovery time, then u is the root of an SCC
    if (low[u] === disc[u]) {
      // Create a new SCC
      const scc: number[] = [];
      let w: number;
      // Pop vertices from the stack until u is reached
      do {
        w = stack.pop()!;
        // Mark vertex w as no longer being on the stack
        onStack[w] = false;
        // Add vertex w to the current SCC
        scc.push(w);
      } while (w !== u);
      // Add the SCC to the list of SCCs
      sccs.push(scc);
    }
  }

  // Iterate through all vertices in the graph
  for (let i = 0; i < n; i++) {
    // If vertex i has not been visited, call DFS on it
    if (disc[i] === -1) {
      dfs(i);
    }
  }

  // Return the list of strongly connected components
  return sccs;
}

