function carFleet(target: number, position: number[], speed: number[]): number {
    // Create an array of pairs, where each pair contains the position and speed of a car.
    const pair: number[][] = position.map((p, i) => [p, speed[i]]);

    // Initialize an empty stack to store the arrival times of the leading cars of each fleet.
    const stack: number[] = [];

    // Sort the array of pairs in reverse order based on the position of the cars.
    // Iterate through the sorted array of pairs.
    for (const [p, s] of pair.sort((a, b) => a[0] - b[0]).reverse()) {
        // Calculate the time it takes for the current car to reach the target.
        const timeToTarget = (target - p) / s;
        // Push the arrival time onto the stack.
        stack.push(timeToTarget);

        // If the stack has at least two elements and the arrival time of the last car added is less than or equal to the arrival time of the second to last car,
        // it means the last car joins the fleet represented by the second to last car. Pop the last car from the stack.
        if (
            stack.length >= 2 &&
            stack[stack.length - 1] <= stack[stack.length - 2]
        ) {
            stack.pop();
        }
    }

    // After iterating through all the cars, the number of elements in the stack is the number of car fleets.
    return stack.length;
}

