    // Create an array of car objects, each containing its position and speed.
    const cars = position.map((p, i) => ({ pos: p, spd: speed[i] }));
    // Sort the cars by position in descending order (farthest to closest).
    cars.sort((a, b) => b.pos - a.pos);

    // Initialize the number of fleets to 0.
    let fleets = 0;
    // Initialize the time it takes for the current fleet leader to reach the target to 0.
    let currentFleetTime = 0;

    // Iterate through the sorted cars.
    for (const car of cars) {
        // Calculate the time it takes for the current car to reach the target.
        const timeToTarget = (target - car.pos) / car.spd;
        // If the car's time to reach the target is greater than the current fleet's time,
        // it means this car will not catch up to the current fleet and will form a new fleet.
        if (timeToTarget > currentFleetTime) {
            // Increment the number of fleets.
            fleets++;
            // Update the current fleet's time to the time it takes for this car to reach the target.
            currentFleetTime = timeToTarget;
        }
    }

    // Return the total number of fleets.
    return fleets;
}

