        int left = 0, right = height.length - 1;

        // Initialize the maximum area found so far to 0.
        int maxArea = 0;

        // Iterate while the left pointer is less than the right pointer.
        while (left < right) {
            // Calculate the width of the current container.
            int width = right - left;

            // Determine the height of the current container, which is the minimum of the two heights.
            int currentHeight = Math.min(height[left], height[right]);

            // Calculate the area of the current container.
            int currentArea = width * currentHeight;

            // Update the maximum area if the current area is larger.
            maxArea = Math.max(maxArea, currentArea);

            // Move the pointer that points to the smaller height towards the center.
            // The goal is to find a potentially taller height that could yield a larger area.
            if (height[left] < height[right]) {
                left++; // Move the left pointer to the right.
            } else {
                right--; // Move the right pointer to the left.
            }
        }

        // Return the maximum area found.
        return maxArea;
    }
}

