function letterCombinations(digits: string): string[] {
    // If the input digits string is empty, return an empty array.
    if (!digits) return [];

    // Initialize an empty array to store the resulting letter combinations.
    const res: string[] = [];

    // Define a mapping between digits and their corresponding letters.
    const digitToChar: Record<string, string> = {
        "2": "abc",
        "3": "def",
        "4": "ghi",
        "5": "jkl",
        "6": "mno",
        "7": "pqrs",
        "8": "tuv",
        "9": "wxyz"
    };

    // Define a recursive backtracking function to generate combinations.
    function backtrack(i: number, curStr: string): void {       // Base case: If the current string's length equals the input digits' length,
        // it means we have a valid combination, so add it to the result array and return.
        if (curStr.length === digits.length) {
            res.push(curStr);
            return;
        }

        // Iterate through the letters corresponding to the current digit.
        for (const c of digitToChar[digits[i]]) {
            // Recursively call backtrack with the next digit and the current string appended with the current letter.
            backtrack(i + 1, curStr + c);
        }
    }

    // Start the backtracking process with the first digit (index 0) and an empty string.
    backtrack(0, "");
    // Return the array of letter combinations.
    return res;
}

