const LOG = 15; // Assuming a maximum tree size of 2^15.  This determines the maximum depth the algorithm can handle.

function binaryLifting(graph: number[][], root: number): {
  up: number[][];
  depth: number[];
  kthAncestor: (node: number, k: number) => number;
  lca: (u: number, v: number) => number;
} {
  const n = graph.length; // Number of nodes in the graph
  // up[i][j] stores the 2^j-th ancestor of node i.
  const up: number[][] = Array(n).fill(null).map(() => Array(LOG).fill(-1));
  const depth: number[] = Array(n).fill(0); // depth[i] stores the depth of node i from the root.

  // DFS function to precompute the 'up' table and 'depth' array.
  function dfs(node: number, parent: number) {
    up[node][0] = parent; // The immediate parent (2^0-th ancestor) of the node.

    // Iterate through powers of 2 to compute the 2^j-th ancestor.
    for (let j = 1; j < LOG; j++) {
      // If the 2^(j-1)-th ancestor exists, then the 2^j-th ancestor is the
      // 2^(j-1)-th ancestor of the 2^(j-1)-th ancestor.
      if (up[node][j - 1] !== -1) {
        up[node][j] = up[up[node][j - 1]][j - 1];
      }
    }

    // Recursively call DFS for all children of the current node.
    for (const child of graph[node]) {
      if (child !== parent) {
        depth[child] = depth[node] + 1; // Depth of the child is one more than the parent.
        dfs(child, node);
      }
    }
  }

  dfs(root, -1); // Start DFS from the root node with no parent (-1).

  // Function to find the k-th ancestor of a given node.
  function kthAncestor(node: number, k: number): number {
    // Iterate through the bits of k.
    for (let j = 0; j < LOG; j++) {
      // If the j-th bit of k is set, then we move the node up by 2^j ancestors.
      if ((k & (1 << j)) !== 0) {
        node = up[node][j];
        if (node === -1) break; // If we reach the root (or beyond), return -1.
      }
    }
    return node;
  }

  // Function to find the Lowest Common Ancestor (LCA) of two nodes u and v.
  function lca(u: number, v: number): number {
    // Ensure that u is deeper than v.
    if (depth[u] < depth[v]) [u, v] = [v, u];

    // Bring u to the same depth as v using kthAncestor.
    let diff = depth[u] - depth[v];
    u = kthAncestor(u, diff);

    // If u and v are now the same node, then it's the LCA.
    if (u === v) return u;

    // Iterate from the highest power of 2 down to 0.
    // Move u and v up the tree together as long as their 2^j-th ancestors are different.
    for (let j = LOG - 1; j >= 0; j--) {
      if (up[u][j] !== up[v][j]) {
        u = up[u][j];
        v = up[v][j];
      }
    }

    // The parent of u (or v) is the LCA.
    return up[u][0];
  }

  return { up, depth, kthAncestor, lca }; // Return the precomputed data and query functions.
}

