        private int[] depth; // depth[i] stores the depth of node i from the root
        private int LOG;     // LOG is the maximum power of 2 needed to cover the tree's height

        public TreeAncestor(int n, int[] parent) {
            // Calculate the maximum height of the tree (in powers of 2)
            LOG = (int) (Math.log(n) / Math.log(2)) + 1;

            // Initialize the 'up' table.  up[i][j] will store the 2^j-th ancestor of node i.
            up = new int[n][LOG];

            // Initialize the depth array
            depth = new int[n];

            // Build the adjacency list representation of the tree
            List<List<Integer>> graph = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                graph.add(new ArrayList<>());
            }

            // Populate the adjacency list based on the parent array.
            // Note: Since the tree is undirected in the graph representation for DFS,
            // we add both parent -> child and child -> parent edges.
            for (int i = 0; i < n; i++) {
                if (parent[i] != -1) {
                    graph.get(i).add(parent[i]);
                    graph.get(parent[i]).add(i);
                }
                Arrays.fill(up[i], -1); // Initialize all entries in 'up' to -1 (no ancestor)
            }

            // Find the root node (the node with parent -1)
            int root = 0;
            for (int i = 0; i < n; ++i) {
                if (parent[i] == -1) {
                    root = i;
                    break;
                }
            }

            // Perform Depth-First Search (DFS) to precompute ancestors and depths
            dfs(root, -1, graph);
        }

        private void dfs(int node, int parent, List<List<Integer>> graph) {
            // Set the immediate parent (2^0-th ancestor) of the current node
            up[node][0] = parent;

            // Compute the 2^j-th ancestors for j > 0 using dynamic programming.
            // up[node][j] = up[up[node][j-1]][j-1]
            // This means the 2^j-th ancestor of 'node' is the 2^(j-1)-th ancestor of the 2^(j-1)-th ancestor of 'node'.
            for (int j = 1; j < LOG; j++) {
                if (up[node][j - 1] != -1) {
                    up[node][j] = up[up[node][j - 1]][j - 1];
                }
            }

            // Recursively call DFS for each child of the current node
            for (int child = 0; child < graph.get(node).size(); child++) {
                int realChild = graph.get(node).get(child);
                if (realChild != parent) {
                    // Update the depth of the child
                    depth[realChild] = depth[node] + 1;

                    // Recursive call for the child
                    dfs(realChild, node, graph);
                }
            }
        }

        public int kthAncestor(int node, int k) {
            // Iterate through the bits of 'k' to find the k-th ancestor.
            // If the j-th bit of 'k' is set, it means we need to jump 2^j levels up.
            for (int j = 0; j < LOG; j++) {
                if ((k & (1 << j)) != 0) {
                    node = up[node][j]; // Move the node to its 2^j-th ancestor
                    if (node == -1) break; // If we reach the root (no ancestor), stop.
                }
            }
            return node;
        }

        public int lca(int u, int v) {
            // Ensure that 'u' is deeper than 'v'.  If not, swap them.
            if (depth[u] < depth[v]) {
                int temp = u;
                u = v;
                v = temp;
            }

            // Bring 'u' to the same depth as 'v' using the kthAncestor function.
            int diff = depth[u] - depth[v];
            u = kthAncestor(u, diff);

            // If 'u' and 'v' are the same node, then that's the LCA.
            if (u == v) return u;

            // Iterate from the highest power of 2 down to 0.
            // Move both 'u' and 'v' upwards as long as their 2^j-th ancestors are different.
            for (int j = LOG - 1; j >= 0; j--) {
                if (up[u][j] != up[v][j]) {
                    u = up[u][j];
                    v = up[v][j];
                }
            }

            // The LCA is the parent of 'u' (or 'v') at this point.
            return up[u][0];
        }
    }
