function findTargetSumWays(nums: number[], target: number): number {
    // Calculate the sum of all numbers in the input array.
    let sum = 0;
    for (const num of nums) {
        sum += num;
    }

    // If the absolute value of the target is greater than the sum, it's impossible to reach the target.
    if (Math.abs(target) > sum) {
        return 0;
    }

    // If (sum + target) is odd, it's impossible to find a valid partition.
    if ((sum + target) % 2 !== 0) {
        return 0;
    }

    // Calculate the new target: (sum + target) / 2. This is the sum that the positive subset should have.
    const newTarget = (sum + target) / 2;

    // Initialize a DP array `dp` of size newTarget + 1, filled with 0s. dp[i] represents the number of subsets that sum up to `i`.
    const dp: number[] = new Array(newTarget + 1).fill(0);
    // Base case: dp[0] = 1 because there's one way to achieve a sum of 0 (by selecting an empty subset).
    dp[0] = 1;

    // Iterate through the numbers in `nums`.
    for (const num of nums) {
        // Iterate through the `dp` array from `newTarget` down to `num`.
        for (let j = newTarget; j >= num; j--) {
            // Update `dp[j]` by adding `dp[j - num]` to it.
            // This means that the number of ways to reach sum `j` is increased by the number of ways to reach sum `j - num`.
            dp[j] += dp[j - num];
        }
    }

    // Return dp[newTarget], which represents the number of subsets that sum up to newTarget.
    return dp[newTarget];
}

