function characterReplacement(s: string, k: number): number {
    // Create a map to store the frequency of each character in the current window.
    const count: { [char: string]: number } = {};
    // Initialize the result to 0. This will store the length of the longest valid substring.
    let res: number = 0;
    // Initialize the left pointer of the sliding window to 0.
    let l: number = 0;
    // Initialize the maximum frequency of any character in the current window to 0.
    let maxf: number = 0;

    // Iterate through the string using the right pointer of the sliding window.
    for (let r: number = 0; r < s.length; r++) {
        // Update the frequency of the character at the right pointer.
        count[s[r]] = 1 + (count[s[r]] || 0);
        // Update the maximum frequency seen so far in the current window.
        maxf = Math.max(maxf, count[s[r]]);

        // While the number of replacements needed to make the substring valid is greater than k,
        // shrink the window from the left.
        while ((r - l + 1) - maxf > k) {
            // Decrement the frequency of the character at the left pointer.
            count[s[l]] -= 1;
            // Move the left pointer one step to the right.
            l += 1;
        }

        // Update the result with the maximum window size seen so far.
        res = Math.max(res, r - l + 1);
    }

    // Return the length of the longest valid substring.
    return res;
}

