function diameterOfBinaryTree(root: TreeNode | null): number {
    let res = 0; // This variable will store the maximum diameter found so far

    // The DFS function calculates the height of the current node's subtree
    // and simultaneously updates the maximum diameter encountered.
    // Height is defined as the number of edges from the node to the deepest leaf.
    // A leaf node has a height of 0. A null node is considered to have a height of -1.
    function dfs(node: TreeNode | null): number {
        // Base case: If the node is null, it contributes -1 to the height.
        // This allows a leaf node (with two null children) to correctly calculate its height as 0.
        if (!node) {
            return -1;
        }

        // Recursively calculate the height of the left and right subtrees.
        const leftHeight = dfs(node.left);
        const rightHeight = dfs(node.right);

        // Calculate the diameter passing *through* the current node.
        // This path is (left_subtree_height + 1 edge to node) + (right_subtree_height + 1 edge to node).
        // Since leftHeight and rightHeight already account for edges, the total edges are:
        // (leftHeight + 1) + (rightHeight + 1) = leftHeight + rightHeight + 2.
        // We update 'res' with the maximum of its current value and this new potential diameter.
        res = Math.max(res, 2 + leftHeight + rightHeight);

        // Return the height of the current node's subtree.
        // The height of a node is 1 (for the edge to its child) plus the maximum height of its children's subtrees.
        return 1 + Math.max(leftHeight, rightHeight);
    }

    // Start the DFS traversal from the root.
    dfs(root);

    // After traversing the entire tree, 'res' will hold the maximum diameter found.
    return res;
}

