class Solution {
    // Main function to calculate the sum of elements within the given range [left, right] in the nums array using a segment tree.
    public:
    int solution(vector<int>& nums, int left, int right) { // O(n) space, O(n) build, O(log n) query
        int n = nums.size();
        // Create a segment tree vector. The size is 4 * n because in the worst case, a complete binary tree requires 2n - 1 nodes, and for a segment tree, we need at most 4n nodes.  
        vector<int> tree(4 * n, 0);

        // Build the segment tree using the input array nums.
        buildTree(tree, nums, 0, 0, n - 1);

        // Query the segment tree to get the sum of elements in the range [left, right].
        return queryTree(tree, 0, 0, n - 1, left, right);
    }

    // Function to build the segment tree.
    // tree: The segment tree vector.
    // nums: The input array.
    // node: The current node index in the segment tree.
    // start: The start index of the current segment in the input array.
    // end: The end index of the current segment in the input array.
    void buildTree(vector<int>& tree, vector<int>& nums, int node, int start, int end) {

        // Base case: If the segment contains only one element.
        if (start == end) {
            // Store the value of the single element in the corresponding node of the segment tree.
            tree[node] = nums[start];
            return;
        }

        // Calculate the middle index of the current segment.
        int mid = (start + end) / 2;

        // Recursively build the left subtree for the segment [start, mid].
        buildTree(tree, nums, 2 * node + 1, start, mid);
        // Recursively build the right subtree for the segment [mid + 1, end].
        buildTree(tree, nums, 2 * node + 2, mid + 1, end);

        // The value of the current node is the sum of its children.
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
    }

    // Function to query the segment tree for the sum of elements in the range [left, right].
    // tree: The segment tree vector.
    // node: The current node index in the segment tree.
    // start: The start index of the current segment in the input array.
    // end: The end index of the current segment in the input array.
    // left: The start index of the query range.
    // right: The end index of the query range.
    int queryTree(vector<int>& tree, int node, int start, int end, int left, int right) {

        // If the query range is completely outside the current segment, return 0.
        if (left > end || right < start)
            return 0;

        // If the query range completely covers the current segment, return the value of the current node.
        if (left <= start && end <= right)
            return tree[node];

        // Calculate the middle index of the current segment.
        int mid = (start + end) / 2;

        // Recursively query the left subtree for the intersection of the query range and the left subtree's segment.
        int p1 = queryTree(tree, 2 * node + 1, start, mid, left, right);
        // Recursively query the right subtree for the intersection of the query range and the right subtree's segment.
        int p2 = queryTree(tree, 2 * node + 2, mid + 1, end, left, right);

        // Return the sum of the results from the left and right subtrees.
        return p1 + p2;
    }
};

