public boolean wordBreak(String s, List<String> wordDict) {
    // Convert dictionary to a set for fast lookup
    Set<String> wordSet = new HashSet<>(wordDict);

    // Queue to store starting indices
    Queue<Integer> queue = new LinkedList<>();

    // visited[i] means index i has already been processed
    boolean[] visited = new boolean[s.length()];

    // Start BFS from index 0
    queue.offer(0);

    while (!queue.isEmpty()) {
        int start = queue.poll();

        // Skip if this index was already visited
        if (visited[start]) {
            continue;
        }
        visited[start] = true;

        // Try all possible end positions
        for (int end = start + 1; end <= s.length(); end++) {
            // Check if substring exists in dictionary
            if (wordSet.contains(s.substring(start, end))) {
                // If we reached the end, segmentation is possible
                if (end == s.length()) {
                    return true;
                }
                // Otherwise, continue BFS from this position
                queue.offer(end);
            }
        }
    }

    // If BFS finishes without reaching the end
    return false;
}

