function trap(height: number[]): number {
    if (!height.length) return 0;

    let l = 0;
    let r = height.length - 1;

    let leftMax = height[l];
    let rightMax = height[r];
    let res = 0;

    while (l < r) {
        if (leftMax < rightMax) {
            // The water level is limited by the current leftMax
            l++; // Move left pointer inward
            leftMax = Math.max(leftMax, height[l]); // Update leftMax with the highest bar seen from the left
            res += leftMax - height[l]; // Add trapped water at the new 'l' position
        } else {
            // The water level is limited by the current rightMax
            r--; // Move right pointer inward
            rightMax = Math.max(rightMax, height[r]); // Update rightMax with the highest bar seen from the right
            res += rightMax - height[r]; // Add trapped water at the new 'r' position
        }
    }

    return res;
}

