            return 0;
        }

        int left = 0;
        int right = height.length - 1;
        int leftMax = 0;
        int rightMax = 0;
        int totalWater = 0;

        while (left < right) {
            if (height[left] < height[right]) {
                // The water level is limited by height[left]
                // If current height[left] is greater than or equal to leftMax,
                // it means this bar can potentially hold water to its right,
                // but it cannot be filled from the left side yet.
                // So, update leftMax and move the left pointer.
                if (height[left] >= leftMax) {
                    leftMax = height[left];
                } else {
                    // If height[left] is less than leftMax,
                    // water can be trapped at this position.
                    // The amount of water is leftMax - height[left].
                    totalWater += leftMax - height[left];
                }
                left++;
            } else {
                // The water level is limited by height[right]
                // Similar logic as above, but from the right side.
                if (height[right] >= rightMax) {
                    rightMax = height[right];
                } else {
                    // If height[right] is less than rightMax,
                    // water can be trapped at this position.
                    // The amount of water is rightMax - height[right].
                    totalWater += rightMax - height[right];
                }
                right--;
            }
        }

        return totalWater;
    }
