    const n = s.length;
    const m = t.length;

    // dp[i][j] represents the number of distinct subsequences of s[0...i-1]
    // that equals t[0...j-1]
    const dp: number[][] = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0));

    // If t is an empty string, then there is exactly one subsequence (empty string)
    for (let i = 0; i <= n; i++) {
        dp[i][0] = 1;
    }

    // If s is an empty string, then there are no subsequences that equals t (unless t is also empty, which is handled above)
    // therefore, dp[0][j] remains 0 for all j > 0.

    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            if (s[i - 1] === t[j - 1]) {
                // If the characters match, then we have two options:
                // 1. Use the character in s to form the subsequence.
                // 2. Don't use the character in s to form the subsequence.
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
            } else {
                // If the characters don't match, then we can't use the character in s
                // to form the subsequence. So, the number of distinct subsequences
                // remains the same as s[0...i-2].
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    return dp[n][m];
}

