function evalRPN(tokens: string[]): number {
    const stack: number[] = [];

    for (const token of tokens) {
        if (token === "+") {
            // For addition, order of operands does not matter.
            // Pop two operands, add them, and push the result.
            stack.push(stack.pop()! + stack.pop()!);
        } else if (token === "-") {
            // For subtraction, order matters: b - a.
            // Pop 'a' (second operand), then 'b' (first operand).
            const a = stack.pop()!;
            const b = stack.pop()!;
            stack.push(b - a);
        } else if (token === "*") {
            // For multiplication, order of operands does not matter.
            // Pop two operands, multiply them, and push the result.
            stack.push(stack.pop()! * stack.pop()!);
        } else if (token === "/") {
            // For division, order matters: Math.trunc(b / a).
            // Pop 'a' (divisor), then 'b' (dividend).
            const a = stack.pop()!;
            const b = stack.pop()!;
            // Use Math.trunc to truncate toward zero as per problem statement.
            stack.push(Math.trunc(b / a));
        } else {
