public static class Solution {
    public int evalRPN(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>(); // Using Deque as a stack for better practice and performance

        for (String token : tokens) {
            switch (token) {
                case "+":
                    // For addition, order of operands doesn't matter (commutative)
                    stack.push(stack.pop() + stack.pop());
                    break;
                case "-":
                    // Order matters: b - a. Second operand (a) is popped first.
                    int a_minus = stack.pop();
                    int b_minus = stack.pop();
                    stack.push(b_minus - a_minus);
                    break;
                case "*":
                    // For multiplication, order of operands doesn't matter (commutative)
                    stack.push(stack.pop() * stack.pop());
                    break;
                case "/":
                    // Order matters: b / a. Second operand (a) is popped first.
                    int a_div = stack.pop();
                    int b_div = stack.pop();
                    // Java's integer division automatically truncates toward zero, matching the problem's requirement.
                    stack.push(b_div / a_div);
                    break;
                default:
                    // If it's not an operator, it must be a number.
                    stack.push(Integer.parseInt(token));
                    break;
            }
        }

        // The final result will be the only element left in the stack
        return stack.pop();
    }
}

