function singleNumber(nums: number[]): number {
    // Initialize a variable 'res' to 0. This variable will accumulate the XOR sum of all numbers.
    // The reason for initializing with 0 is that XORing any number with 0 results in the number itself (e.g., x ^ 0 = x).
    let res = 0;

    // Iterate through each number 'n' in the input array 'nums'.
    // This loop processes every element exactly once, ensuring O(N) time complexity.
    for (const n of nums) {
        // Perform a bitwise XOR operation between the current accumulated result 'res' and the current number 'n'.
        // The key properties of XOR used here are:
        // 1. x ^ x = 0 (XORing a number with itself results in 0).
        // 2. x ^ 0 = x (XORing a number with 0 results in the number itself).
        // 3. XOR is commutative (a ^ b = b ^ a) and associative (a ^ (b ^ c) = (a ^ b) ^ c).
        //
        // When all numbers in the array are XORed together, any number that appears twice will cancel itself out
        // because (a ^ a) evaluates to 0. Since all numbers appear twice except for one, all the paired numbers
        // will effectively become 0, leaving only the unique single number in 'res'.
        // For example, if nums = [2, 1, 4, 2, 1], the operations would be:
        // res = 0 ^ 2 = 2
        // res = 2 ^ 1 = 3
        // res = 3 ^ 4 = 7
        // res = 7 ^ 2 = (4 ^ 2 ^ 1) ^ 2 = 4 ^ (2 ^ 2) ^ 1 = 4 ^ 0 ^ 1 = 4 ^ 1 = 5
        // res = 5 ^ 1 = (4 ^ 1) ^ 1 = 4 ^ (1 ^ 1) = 4 ^ 0 = 4
        // The final result 'res' will be 4, which is the single number.
        res ^= n;
    }

    // After iterating through all elements, 'res' holds the value of the single number that appeared only once.
    // All other numbers, having appeared twice, cancelled each other out through the XOR operations.
    return res;
}

