function maxCoins(nums: number[]): number {
    // Pad the input array with 1s at the beginning and end to handle boundary conditions gracefully.
    nums = [1, ...nums, 1];

    // Get the length of the padded array.
    const n = nums.length;
    // Initialize a 2D DP table with dimensions n x n, filled with 0s.
    // dp[i][j] will store the maximum coins obtainable by bursting balloons between indices i and j (exclusive).
    const dp: number[][] = Array(n).fill(null).map(() => Array(n).fill(0));

    // Iterate through different lengths of subarrays (from 2 to n-1).
    for (let len = 2; len < n; len++) {
        // Iterate through all possible start indices for the subarray.
        for (let i = 1; i < n - len + 1; i++) {
            // Calculate the end index of the subarray based on the current start index and length.
            let j = i + len - 1;
            // Iterate through all possible last balloons to burst within the subarray (i, j).
            for (let k = i; k < j; k++) {
                // Calculate the coins obtained by bursting balloon k last. This is the key DP step.
                // dp[i][k] represents the maximum coins from bursting balloons in the range (i, k).
                // dp[k+1][j] represents the maximum coins from bursting balloons in the range (k+1, j).
                // nums[i-1] * nums[k] * nums[j] represents the coins obtained by bursting balloon k, considering its neighbors.
                // Update dp[i][j] with the maximum value.
                dp[i][j] = Math.max(dp[i][j], dp[i][k] + dp[k + 1][j] + nums[i - 1] * nums[k] * nums[j]);
            }
        }
    }

    // Return the maximum coins obtainable by bursting all balloons, which is stored in dp[1][n-1].
    return dp[1][n - 1];
}

