public static class Solution {
    public int maxCoins(int[] nums) {
        // n stores the length of the original input array.
        int n = nums.length;

        // paddedNums is created to add padding of 1 at the beginning and end of the array.
        // This handles boundary conditions gracefully.
        int[] paddedNums = new int[n + 2];

        // Set the first and last elements of paddedNums to 1.
        paddedNums[0] = paddedNums[n + 1] = 1;

        // Copy the original nums array into paddedNums, starting from index 1.
        System.arraycopy(nums, 0, paddedNums, 1, n);

        // dp[i][j] stores the maximum coins obtainable by bursting balloons in the range (i, j).
        int[][] dp = new int[n + 2][n + 2];

        // The outer loop iterates through different lengths of the subproblems (ranges).
        // The length starts from 2 because a range of length 1 (single balloon) is already implicitly handled.
        for (int len = 2; len < n + 2; len++) {
            // The inner loop iterates through the possible left boundaries of the range.
            for (int left = 0; left < n + 2 - len; left++) {
                // Calculate the right boundary of the range.
                int right = left + len;

                // This loop iterates through all possible 'last' balloons to burst within the range (left, right).
                for (int i = left + 1; i < right; i++) {
                    // dp[left][right] is updated with the maximum coins obtainable by bursting balloon i last.
                    // The coins are calculated as the sum of:
                    //   - coins from bursting balloons in the range (left, i)
                    //   - coins from bursting balloon i (paddedNums[left] * paddedNums[i] * paddedNums[right])
                    //   - coins from bursting balloons in the range (i, right)
                    dp[left][right] = Math.max(dp[left][right],
                                               dp[left][i] + paddedNums[left] * paddedNums[i] * paddedNums[right] + dp[i][right]);
                }
            }
        }

        // dp[0][n+1] represents the maximum coins obtained by bursting all balloons in the padded array.
        return dp[0][n + 1];
    }
}

