function copyRandomList(head: Node | null): Node | null {
    // A map to store the mapping from original nodes to their copied counterparts.
    // It's crucial to map null to null to handle null `next` and `random` pointers gracefully.
    const oldToCopy = new Map<Node | null, Node | null>();
    oldToCopy.set(null, null);

    let curr = head;

    // First pass: Create all new nodes and store their mapping.
    // We only create nodes and copy their `val` here. Pointers are not set yet.
    while (curr) {
        const copy = new Node(curr.val);
        oldToCopy.set(curr, copy);
        curr = curr.next;
    }

    // Reset curr to the head of the original list for the second pass.
    curr = head;

    // Second pass: Connect `next` and `random` pointers for all copied nodes.
    while (curr) {
        // Get the copied node corresponding to the current original node.
        const copy = oldToCopy.get(curr)!; // We use '!' because we know curr exists in the map from the first pass.

        // Set the `next` pointer of the copied node.
        // If `curr.next` is null, oldToCopy.get(null) will return null, as set initially.
        copy.next = oldToCopy.get(curr.next) ?? null;

        // Set the `random` pointer of the copied node.
        // If `curr.random` is null, oldToCopy.get(null) will return null.
        copy.random = oldToCopy.get(curr.random) ?? null;

        // Move to the next original node.
        curr = curr.next;
    }

    // Return the head of the copied list, which corresponds to the original head.
    return oldToCopy.get(head) ?? null;
}

