        // At this stage, only the 'val' of the new nodes is set; 'next' and 'random' pointers are not yet connected.
        while (curr != nullptr) {
            Node* copy = new Node(curr->val);
            oldToCopy[curr] = copy;
            curr = curr->next;
        }

        // Reset curr to the head of the original list for the second pass.
        curr = head;

        // Second pass: Iterate through the original list again to connect the 'next' and 'random' pointers of the copied nodes.
