        // Then, set the 'next' pointer of the copy to the copy of 'curr->next' (retrieved from the map).
        // Similarly, set the 'random' pointer of the copy to the copy of 'curr->random' (retrieved from the map).
        while (curr != nullptr) {
            Node* copy = oldToCopy[curr];
            // Use oldToCopy[curr->next] to get the copied version of the next node.
            // If curr->next is nullptr, oldToCopy[nullptr] correctly returns nullptr.
            copy->next = oldToCopy[curr->next];
            // Use oldToCopy[curr->random] to get the copied version of the random node.
            // If curr->random is nullptr, oldToCopy[nullptr] correctly returns nullptr.
            copy->random = oldToCopy[curr->random];
            curr = curr->next;
