public static class Solution {
    public int uniquePaths(int m, int n) {
        // Initialize the last row with 1s. This represents the base case where
        // there is only one path to reach any cell in the last row (going only right).
        int[] row = new int[n];
        for (int i = 0; i < n; i++) {
            row[i] = 1;
        }

        // Build the rows from bottom to top (from the second last row up to the first row).
        // We iterate m - 1 times because the last row is already initialized.
        for (int i = 0; i < m - 1; i++) {
            // Create a new row to store the number of unique paths for the current row.
            int[] newRow = new int[n];
            // The last element of each row is always 1, as there is only one way to reach it
            // (going only down and right from the cells to the right).
            newRow[n - 1] = 1;

            // Fill the row from right to left, calculating the number of unique paths to each cell.
            // The number of unique paths to a cell is the sum of the paths from the cell to its right
            // and the paths from the cell below it (which is stored in the 'row' array).
            for (int j = n - 2; j >= 0; j--) {
                newRow[j] = newRow[j + 1] + row[j];
            }

            // Update the 'row' array to the 'newRow' array, as the 'newRow' now contains the
            // number of unique paths for the current row, which will be used to calculate the
            // number of unique paths for the next row.
            row = newRow;
        }

        // After processing all rows, row[0] contains the number of unique paths from the top-left
        // cell to the bottom-right cell.
        return row[0];
    }
}

