function uniquePaths(m: number, n: number): number {
    // Calculate the total number of steps required to reach the destination.
    // It's (m - 1) steps down + (n - 1) steps right = m + n - 2.
    let total: number = m + n - 2;

    // Determine the smaller value between (m - 1) and (n - 1).  We'll use this as 'k' in the combination formula.
    //  Choosing the smaller value optimizes the calculation since C(n, k) = C(n, n-k).
    let k: number = Math.min(m - 1, n - 1);

    // Initialize the result to 1. This will accumulate the combination value.
    let result: number = 1;

    // Compute the combination C(total, k) using an iterative approach to avoid factorials.
    // The formula C(n, k) = n! / (k! * (n-k)!) can be simplified to avoid large intermediate factorial values.
    // Instead, we calculate it iteratively: C(n, k) = (n * (n-1) * ... * (n-k+1)) / (k * (k-1) * ... * 1)
    for (let i = 1; i <= k; i++) {
        result = result * (total - k + i) / i;
    }

    // Return the calculated number of unique paths.
    return result;
}

