function isMatch(s: string, p: string): boolean {
    // Memoization map to cache results of previously computed (i, j) subproblems.
    // Key format: "i,j" represents indices in the string `s` and pattern `p` respectively.
    const cache = new Map<string, boolean>();

    // DFS helper function to check if the substring starting at `i` matches the subpattern starting at `j`.
    function dfs(i: number, j: number): boolean {
        const key = `${i},${j}`;

        // Step 1: Memoization Lookup.
        // Return the cached result if this state has already been evaluated.
        if (cache.has(key)) {
            return cache.get(key)!;
        }

        // Step 2: Base Cases.
        // Case A: If both the string and the pattern are fully consumed, we have a successful match.
        if (i >= s.length && j >= p.length) {
            return true;
        }

        // Case B: If the pattern is exhausted but the string still has characters, it is a mismatch.
        // Note: If the string is exhausted but the pattern is not, we might still match (e.g., matching "" with "a*").
        if (j >= p.length) {
            return false;
        }

        // Step 3: Determine if the current character in `s` matches the current character in `p`.
        // A match occurs if we are within string bounds AND (characters are identical OR pattern has wildcard '.').
        const match = i < s.length && (s[i] === p[j] || p[j] === ".");

        // Step 4: Handle the '*' Kleene Star wildcard if it exists as the next character in the pattern.
        if (j + 1 < p.length && p[j + 1] === "*") {
            // We have two recursive branches when matching with '*':
            // Branch 1 (Zero occurrences): Skip the current pattern character and the '*' -> dfs(i, j + 2)
            // Branch 2 (One or more occurrences): If there is a character match, consume one character from `s` 
            //                                    and keep the '*' pattern active for subsequent checks -> dfs(i + 1, j)
            const result = dfs(i, j + 2) || (match && dfs(i + 1, j));

            cache.set(key, result);
            return result;
        }

        // Step 5: Handle single character matches (No '*' lookahead).
        // If the current characters match, move both pointers forward by one.
        if (match) {
            const result = dfs(i + 1, j + 1);
            cache.set(key, result);
            return result;
        }

        // Step 6: If no matching condition is satisfied, cache the failure and return false.
        cache.set(key, false);
        return false;
    }

    // Start the recursive matching from the beginning of both string and pattern.
    return dfs(0, 0);
}

