function reverseKGroup(head: ListNode | null, k: number): ListNode | null {
    // Create a dummy node to simplify handling edge cases, especially when the original head is part of the first reversed group.
    // The dummy node always points to the current head of the overall list or the segment being built.
    const dummy = new ListNode(0, head);

    // 'groupPrev' tracks the node *immediately before* the current k-group that is being considered for reversal.
    // Initially, it points to the dummy node, as the first k-group starts after it.
    let groupPrev: ListNode | null = dummy;

    // The main loop continues as long as we can find a full k-group to reverse.
    while (true) {
        // Step 1: Check if a full k-group exists.
        // 'kth' will point to the k-th node *within* the current group (relative to groupPrev.next).
        // If groupPrev is dummy, kth is the k-th node from the original head.
        const kth = getKth(groupPrev, k);

        // If 'kth' is null, it means there are fewer than 'k' nodes remaining from groupPrev.next to the end of the list.
        // In this case, according to the problem statement, these remaining nodes should not be reversed.
        if (!kth) {
            break; // Exit the loop as no more full k-groups can be formed.
        }

        // 'groupNext' points to the node immediately following the 'kth' node.
        // This is effectively the head of the *next* k-group (or null if the current group is the last).
        const groupNext = kth.next;

        // --- Step 2: Reverse the current k-group (from groupPrev.next to kth) ---
        // This is a standard iterative linked list reversal for a sublist.
        // 'prev' will act as the new 'next' pointer for 'curr' nodes during reversal.
        // It starts pointing to 'groupNext' because the original first node of the group (which becomes its tail after reversal)
        // should point to 'groupNext'.
        let prev: ListNode | null = groupNext;
        // 'curr' starts at the first node of the current k-group to be reversed.
        let curr: ListNode | null = groupPrev!.next; // We are certain groupPrev.next exists because kth was found.

        // Loop to reverse pointers for 'k' nodes.
        // It continues as long as 'curr' is within the current k-group, i.e., it hasn't reached 'groupNext'.
        while (curr !== groupNext) {
            const temp = curr!.next; // Temporarily store the next node to avoid losing the reference.
            curr!.next = prev;      // Reverse the 'next' pointer of the current node to point to 'prev'.
            prev = curr;            // Move 'prev' one step forward (it now points to the node just reversed).
            curr = temp;            // Move 'curr' one step forward (to the next node to be reversed).
        }

        // --- Step 3: Reconnect the reversed group to the rest of the list ---
        // 'temp' here is used to store the *original* head of the current k-group (before reversal).
        // After reversal, this node (groupPrev.next before reassignment) is the *tail* of the reversed group.
        const temp = groupPrev!.next; 

        // The node *before* the current group ('groupPrev') should now point to the new head of the reversed group.
        // The new head is 'kth' (since it was the k-th node and is now the first after reversal).
        groupPrev!.next = kth;

        // Update 'groupPrev' for the next iteration.
        // It should now point to the *tail* of the newly reversed group (which was the original head).
        // This ensures 'groupPrev' is correctly positioned to find the next k-group.
        groupPrev = temp;
    }

    // The modified list's head is accessed through dummy.next.
    return dummy.next;
}

function getKth(
    curr: ListNode | null,
    k: number
): ListNode | null {
    // Traverse k steps forward from 'curr'
    while (curr && k > 0) {
        curr = curr.next;
        k--;
    }
    // Return the kth node, or null if not found (i.e., fewer than k nodes were available)
    return curr;
}

public static class Solution {

    // Definition for singly-linked list.
    // This nested class defines the structure of each node in the linked list.
    // public static class ListNode {
