    /**
     * Reverses the nodes of the list `k` at a time.
     * If the number of nodes is not a multiple of `k`, then left-out nodes at the end should remain as they are.
     * This solution uses an iterative approach with O(1) extra space.
     *
     * @param head The head of the linked list.
     * @param k The group size for reversal.
     * @return The head of the modified linked list.
     */
    public ListNode reverseKGroup(ListNode head, int k) {
        // Create a dummy node to simplify handling edge cases, especially when the original head of the list
        // needs to be updated after the first group reversal. The dummy node serves as a fixed reference point.
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        // `groupPrev` points to the node *before* the current k-group that we are about to reverse.
        // Initially, it points to the dummy node. This pointer helps in connecting the reversed group
        // back to the overall list.
        ListNode groupPrev = dummy;

        // The main loop iterates through the linked list, processing one k-group at a time.
        while (true) {
            // 1. Check if a full k-group exists starting from `groupPrev.next`.
            // `kth` will be the last node of the current k-group, if it exists.
            // Example: For D -> 1 -> 2 -> 3 -> 4 -> 5, with k=2 and groupPrev=D, getKth(D, 2) returns node '2'.
            ListNode kth = getKth(groupPrev, k);

            // If `kth` is null, it means there are fewer than `k` nodes remaining from `groupPrev.next`.
            // According to the problem statement, these remaining nodes should not be reversed.
            // So, we break the loop and return the list as it is up to this point.
            if (kth == null) {
                break;
            }

            // `groupNext` stores the node *immediately after* the current k-group.
            // This is crucial for linking the reversed group back to the rest of the list.
            // Example: If kth is '2', groupNext will be '3'.
            ListNode groupNext = kth.next;

            // --- 2. Reverse the current k-group in-place --- 
            // This segment uses the standard iterative linked list reversal logic.
            // `prev` is initialized to `groupNext`. After reversal, the *original* first node of the group
            // (which becomes the *last* node of the reversed group) will point to this `prev` (i.e., `groupNext`).
            ListNode prev = groupNext;
            // `curr` starts at the first node of the current group (e.g., node '1' for the first group).
            ListNode curr = groupPrev.next;

            // Iterate until `curr` reaches `groupNext`, reversing pointers one by one.
            // The loop effectively reverses the segment from `groupPrev.next` up to `kth`.
            while (curr != groupNext) {
                ListNode temp = curr.next; // Store the next node to avoid losing its reference during reversal
                curr.next = prev;          // Reverse the pointer: `curr` now points to `prev`
                prev = curr;               // Move `prev` to the current node (`curr`), which is now the new head of the processed segment
                curr = temp;               // Move `curr` to the next node (from the original list) to continue reversal
            }
            // After this inner loop, `prev` will be the new head of the reversed group (it will be the original `kth` node).
            // `curr` will be `groupNext`.

            // --- 3. Reconnect the reversed group to the main list --- 
            // `tempOriginalHeadOfGroup` stores the node that was originally the first node of the group.
            // After reversal, this node becomes the *tail* of the reversed group.
            ListNode tempOriginalHeadOfGroup = groupPrev.next; // This was, for instance, node '1'.

            // The node *before* the current group (`groupPrev`) must now point to the new head of the reversed group.
            // The new head is `kth` (which is also what `prev` points to after the inner reversal loop).
            groupPrev.next = kth;

            // For the next iteration, `groupPrev` needs to be updated. It should point to the tail of the just-reversed group.
            // This node (`tempOriginalHeadOfGroup`) is now correctly linked to `groupNext` by the inner reversal loop.
            // Example: D -> 2 -> 1, and 1 -> 3. `groupPrev` is updated to '1' for the next group [3,4].
            groupPrev = tempOriginalHeadOfGroup;
        }

        // The `dummy.next` now points to the head of the completely modified list.
        return dummy.next;
    }


    /**
     * Helper function to find the Kth node from a given start node.
     * It traverses `k` steps forward from the `curr` node.
     * If `curr` is the node *before* the group (e.g., a dummy node or the tail of a previous group),
     * `getKth(curr, k)` will return the Kth node *of that group* after 'k' steps.
     * Returns null if there are fewer than `k` nodes available.
     *
     * @param curr The starting node from which to count `k` steps.
     * @param k The number of steps to move forward.
     * @return The node `k` steps away from `curr`, or `null` if the list ends before `k` steps.
     */
    private static ListNode getKth(ListNode curr, int k) {
        // Traverse 'k' steps forward from 'curr'.
        // If `curr` becomes null before `k` steps are completed, it means there are fewer than `k` nodes.
        while (curr != null && k > 0) {
            curr = curr.next;
            k--;
        }
        return curr;
    }
}

