    // Helper function to merge two sorted linked lists.
    function mergeTwoLists(l1: ListNode | null, l2: ListNode | null): ListNode | null {
        // Create a dummy node to simplify the merging process.
        const dummy = new ListNode();
        // 'tail' points to the last node of the merged list.
        let tail: ListNode = dummy;

        // Iterate while both lists have elements.
        while (l1 !== null && l2 !== null) {
            // Compare the values of the current nodes in both lists.
            if (l1.val < l2.val) {
                // If the value in l1 is smaller, append it to the merged list.
                tail.next = l1;
                l1 = l1.next;
            } else {
                // Otherwise, append the value in l2 to the merged list.
                tail.next = l2;
                l2 = l2.next;
            }
            // Move the 'tail' pointer to the newly added node.
            tail = tail.next!;
        }

        // If one of the lists is not empty, append the remaining elements to the merged list.
        if (l1 !== null) {
            tail.next = l1;
        } else if (l2 !== null) {
            tail.next = l2;
        }

        // Return the head of the merged list (excluding the dummy node).
        return dummy.next;
    }

    // Initialize the merged list to null.
    let mergedList: ListNode | null = null;
    // Iterate through the array of linked lists.
    for (let i = 0; i < lists.length; i++) {
        // Merge the current merged list with the next list in the array.
        mergedList = mergeTwoLists(mergedList, lists[i]);
    }

    // Return the final merged sorted list.
    return mergedList;
