    private ListNode mergeKListsHelper(ListNode[] lists, int start, int end) {
        // Base case: if the range contains only one list, return that list.
        if (start == end) {
            return lists[start];
        }

        // Calculate the middle index to divide the range into two halves.
        int mid = start + (end - start) / 2;

        // Recursively merge the left half of the range.
        ListNode left = mergeKListsHelper(lists, start, mid);

        // Recursively merge the right half of the range.
        ListNode right = mergeKListsHelper(lists, mid + 1, end);

        // Merge the two sorted lists obtained from the recursive calls.
        return mergeTwoLists(left, right);
    }

