        ListNode dummy = new ListNode();

        // Initialize a tail pointer to the dummy node.
        ListNode tail = dummy;

        // Iterate through both lists until one of them is exhausted.
        while (l1 != null && l2 != null) {
            // Compare the values of the current nodes.
            if (l1.val < l2.val) {
                // If the value in l1 is smaller, append it to the tail.
                tail.next = l1;
                l1 = l1.next;
            } else {
