function searchMatrix(matrix: number[][], target: number): boolean {
    // Get the number of rows in the matrix.
    const ROWS = matrix.length;
    // Get the number of columns in the matrix.
    // Assumes the matrix is not empty and all rows have the same length.
    const COLS = matrix[0].length;

    // Initialize 'top' pointer for the binary search on rows. Starts at the first row index.
    let top = 0;
    // Initialize 'bot' pointer for the binary search on rows. Starts at the last row index.
    let bot = ROWS - 1;

    // --- Stage 1: Binary Search to find the correct row ---
    // This loop efficiently searches for the row that could potentially contain the target value.
    // It leverages the matrix properties: each row is sorted, and the first element of a row
    // is greater than the last element of the preceding row.
    while (top <= bot) {
        // Calculate the middle row index to check. Math.floor ensures an integer index.
        const row = Math.floor((top + bot) / 2);

        // Check if the target is greater than the last element of the current middle row.
        // If true, the target must be in a row below this 'row' because all elements
        // in the current row and preceding rows are smaller than or equal to matrix[row][COLS - 1].
        if (target > matrix[row][COLS - 1]) {
            top = row + 1; // Move the 'top' pointer to search in the rows below.
        } 
        // Check if the target is less than the first element of the current middle row.
        // If true, the target must be in a row above this 'row' because all elements
        // in the current row and subsequent rows are greater than or equal to matrix[row][0].
        else if (target < matrix[row][0]) {
            bot = row - 1; // Move the 'bot' pointer to search in the rows above.
        } 
        // If neither of the above conditions is met, it implies that the target value
        // falls within the range [matrix[row][0], matrix[row][COLS - 1]].
        // This 'row' is the potential candidate row, so we can stop the row search.
        else {
            break; // Exit the loop, as the candidate row has been identified.
        }
    }

    // --- Edge Case Handling after Stage 1 ---
    // After the first binary search loop, if 'top' has become greater than 'bot',
    // it means that no suitable row was found where the target could possibly exist.
    // This typically occurs if the target is smaller than the first element of the matrix
    // or larger than the last element of the matrix, or if the matrix is empty.
    if (!(top <= bot)) {
        return false; // The target is not in the matrix.
    }

    // Re-calculate the 'row' index. This is necessary because 'row' was declared inside the loop's scope.
    // At this point, 'top' and 'bot' pointers have converged to define the specific row where the target
    // is expected to be found (or 'top' points to the row and 'bot' is 'top-1' if the loop ended naturally without a break, but here it implies a break).
    // This calculation effectively gets the middle index of the now-converged search range for rows.
    const row = Math.floor((top + bot) / 2);

    // Initialize 'l' (left) pointer for the binary search within the chosen row. Starts at the first column index.
    let l = 0;
    // Initialize 'r' (right) pointer for the binary search within the chosen row. Starts at the last column index.
    let r = COLS - 1;

    // --- Stage 2: Binary Search within the identified row ---
    // Now, perform a standard binary search on the specific 'row' identified in Stage 1.
    // This searches for the target value among the elements of that single row.
    while (l <= r) {
        // Calculate the middle column index within the current row's search space.
        const m = Math.floor((l + r) / 2);

        // If the target is greater than the element at the middle column 'm',
        // the target must be in the right half of the current column search space.
        if (target > matrix[row][m]) {
            l = m + 1; // Move 'l' pointer to the right of 'm'.
        }
        // If the target is less than the element at the middle column 'm',
        // the target must be in the left half of the current column search space.
        else if (target < matrix[row][m]) {
            r = m - 1; // Move 'r' pointer to the left of 'm'.
        }
        // If none of the above, it means target == matrix[row][m].
        // The target has been found!
        else {
            return true; // Return true as the target is successfully located.
        }
    }

    // --- Final Check ---
    // If the second binary search loop (Stage 2) completes without finding the target,
    // it means the target is not present in the identified row (and thus not in the entire matrix).
    return false; // Target not found in the matrix.
}

