function minEatingSpeed(piles: number[], h: number): number {
    // Initialize the left boundary for binary search. The minimum possible eating speed is 1 banana per hour.
    let l = 1;
    // Initialize the right boundary for binary search. The maximum possible eating speed is the size of the largest pile,
    // as Koko would at most eat that many bananas in one hour for that pile.
    let r = Math.max(...piles);
    // Initialize the result variable. This will store the minimum valid eating speed found so far.
    // We start with `r` because it's a guaranteed valid speed (even if not optimal) and any valid speed must be less than or equal to it.
    let res = r;

    // Perform binary search within the range [l, r] to find the minimum eating speed 'k'.
    while (l <= r) {
        // Calculate the middle value, which represents our current candidate for the eating speed 'k'.
        // Math.floor is used to ensure 'k' is an integer.
        const k = Math.floor((l + r) / 2);

        // Initialize total hours needed for the current candidate speed 'k'.
        let hours = 0;
        // Iterate through each pile of bananas to calculate the time taken with speed 'k'.
        for (const p of piles) {
            // For each pile 'p', calculate the hours needed. Math.ceil is used because Koko must finish a pile
            // before moving to the next, and even a fraction of an hour counts as a full hour.
            hours += Math.ceil(p / k);
        }

        // Check if Koko can finish all bananas within 'h' hours with the current speed 'k'.
        if (hours <= h) {
            // If 'k' is a feasible speed, it means Koko can finish on time or even faster.
            // We update our result `res` to 'k' because we're looking for the *minimum* such speed.
            res = Math.min(res, k);
            // Since 'k' is feasible, we might be able to find an even smaller speed.
            // So, we narrow our search to the left half [l, k-1].
            r = k - 1;
        } else {
            // If 'k' is not a feasible speed (i.e., 'hours > h'), Koko is eating too slowly.
            // We need a faster speed, so we discard 'k' and search in the right half [k+1, r].
            l = k + 1;
        }
    }

    // After the binary search loop terminates (l > r), 'res' will hold the minimum integer eating speed
    // that allows Koko to finish all bananas within 'h' hours.
    return res;
}

