function merge(intervals: number[][]): number[][] {
    // If the input array is null or empty, return an empty array.
    if (!intervals || intervals.length === 0) {
        return [];
    }

    // Sort the intervals based on their start times in ascending order.
    // This ensures that we process intervals in a logical order for merging.
    intervals.sort((a, b) => a[0] - b[0]);

    // Initialize an array to store the merged intervals.
    const merged: number[][] = [];

    // Initialize the current interval with the first interval in the sorted array.
    let currentInterval = intervals[0];

    // Iterate through the remaining intervals, starting from the second interval.
    for (let i = 1; i < intervals.length; i++) {
        // Get the next interval to compare with the current interval.
        const nextInterval = intervals[i];

        // Check if the current interval overlaps with the next interval.
        // An overlap occurs if the end time of the current interval is greater than or equal to the start time of the next interval.
        if (currentInterval[1] >= nextInterval[0]) {
            // If the intervals overlap, merge them by updating the end time of the current interval.
            // The new end time is the maximum of the end times of the current and next intervals.
            currentInterval[1] = Math.max(currentInterval[1], nextInterval[1]);
        } else {
            // If the intervals do not overlap, add the current interval to the merged array.
            merged.push(currentInterval);
            // Update the current interval to be the next interval.
            currentInterval = nextInterval;
        }
    }

    // After iterating through all the intervals, add the last current interval to the merged array.
    merged.push(currentInterval);

    // Return the array of merged intervals.
    return merged;
}

