function maxAreaOfIsland(grid: number[][]): number {
    const ROWS = grid.length;
    if (ROWS === 0) return 0; // Handle case for an empty grid, though constraints say 1 <= m, n
    const COLS = grid[0].length;
    const visited = new Set<string>(); // Use a Set to store visited cell coordinates as strings "r,c"

    /**
     * Performs a Depth-First Search starting from (r, c) to find the area of the connected island.
     * Marks visited cells to avoid re-counting and infinite recursion.
     * @param r The current row index.
     * @param c The current column index.
     * @returns The area of the island connected to (r, c), or 0 if it's water, out of bounds, or already visited.
     */
    function dfs(r: number, c: number): number {
        // Base cases for recursion:
        // 1. If the current cell is out of grid boundaries.
        // 2. If the current cell contains water (0).
        // 3. If the current cell has already been visited as part of another DFS traversal.
        if (
            r < 0 || r >= ROWS ||
            c < 0 || c >= COLS ||
            grid[r][c] === 0 ||
            visited.has(`${r},${c}`)
        ) {
            return 0;
        }

        // Mark the current cell as visited to prevent re-processing and ensure it's counted once.
        visited.add(`${r},${c}`);

        // The current cell itself contributes 1 to the island's area.
        // Recursively explore all four 4-directionally connected neighbors (up, down, left, right)
        // and sum their contributions to the area.
        return (
            1 + // Area from the current cell
            dfs(r + 1, c) + // Explore down
            dfs(r - 1, c) + // Explore up
            dfs(r, c + 1) + // Explore right
            dfs(r, c - 1)   // Explore left
        );
    }

    let maxArea = 0; // Initialize a variable to keep track of the maximum island area found.

    // Iterate through every cell in the grid.
    // Each cell can potentially be the starting point of a new, unvisited island.
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            // Call DFS for each cell. If it's land and unvisited, DFS will calculate its island's area.
            // If it's water or already visited, DFS will immediately return 0, effectively skipping it.
            maxArea = Math.max(maxArea, dfs(r, c));
        }
    }

    return maxArea; // Return the largest island area found.
}

