    for (let i = m - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            // If the characters at the current positions in both strings match,
            // it means that this character is part of the LCS.  Therefore, we
            // increment the length of LCS found so far (dp[i+1][j+1]) by 1.
            if (text1[i] === text2[j]) {
                dp[i][j] = 1 + dp[i + 1][j + 1];
            } else {
