  private store: Map<string, [string, number][]>;

  constructor() {
    // key -> list of [value, timestamp]
    this.store = new Map();
  }

  set(key: string, value: string, timestamp: number): void {
    // If the key doesn't exist, create a new list for it
    if (!this.store.has(key)) {
      this.store.set(key, []);
    }

    // Push the new [value, timestamp] pair to the list associated with the key
    this.store.get(key)!.push([value, timestamp]);
  }

  get(key: string, timestamp: number): string {
    // Initialize the result to an empty string (default if no value is found)
    let res = "";
    // Get the list of [value, timestamp] pairs for the given key
    // If the key doesn't exist, default to an empty array
    const values = this.store.get(key) || [];

    // Binary Search to find the largest timestamp less than or equal to the given timestamp
    let left = 0;
    let right = values.length - 1;

    // Standard binary search loop
    while (left <= right) {
      // Calculate the middle index
      const mid = Math.floor((left + right) / 2);

      // If the timestamp at the middle index is less than or equal to the target timestamp
      if (values[mid][1] <= timestamp) {
        // Update the result to the value at the middle index
        res = values[mid][0];
        // Move the left pointer to search for a potentially larger timestamp
        left = mid + 1;
      } else {
        // If the timestamp at the middle index is greater than the target timestamp,
        // Move the right pointer to search in the left half
        right = mid - 1;
      }
    }

    // Return the result (the value with the largest timestamp <= the given timestamp)
    return res;
  }
}

