function alienOrder(words: string[]): string {
  // Build the graph and in-degree map
  const adj: Map<string, string[]> = new Map(); // Adjacency list representing the graph
  const inDegree: Map<string, number> = new Map(); // In-degree of each character

  // Initialize in-degree for all unique characters
  for (const word of words) {
    for (const char of word) {
      inDegree.set(char, 0); // Initially, in-degree is 0
    }
  }

  // Build the graph by comparing adjacent words
  for (let i = 0; i < words.length - 1; i++) {
    const word1 = words[i];
    const word2 = words[i + 1];
    const minLength = Math.min(word1.length, word2.length);

    for (let j = 0; j < minLength; j++) {
      if (word1[j] !== word2[j]) {
        // Found a new edge
        if (!adj.has(word1[j])) {
          adj.set(word1[j], []); // Initialize adjacency list if not present
        }

        if (!adj.get(word1[j])!.includes(word2[j])) {
          adj.get(word1[j])!.push(word2[j]); // Add the edge
          inDegree.set(word2[j], inDegree.get(word2[j])! + 1); // Increment in-degree of the destination
        }
        break; // Only the first different character matters
      }
      if (j === minLength - 1 && word1.length > word2.length) {
        // Invalid order: "abc" comes before "ab"
        return "";
      }
    }
  }

  // Topological sort using BFS
  const queue: string[] = [];
  for (const [char, degree] of inDegree) {
    if (degree === 0) {
      queue.push(char); // Add nodes with in-degree 0 to the queue
    }
  }

  let result = "";
  let count = 0;

  while (queue.length > 0) {
    const char = queue.shift()!;
    result += char; // Append the character to the result
    count++; // Increment the count of visited nodes

    if (adj.has(char)) {
      for (const neighbor of adj.get(char)!) {
        inDegree.set(neighbor, inDegree.get(neighbor)! - 1); // Reduce in-degree of neighbors
        if (inDegree.get(neighbor) === 0) {
          queue.push(neighbor); // Add neighbors with in-degree 0 to the queue
        }
      }
    }
  }

  // Check for cycle: if not all nodes were visited
  if (count !== inDegree.size) {
    return ""; // Cycle detected
  }

  return result;
}

