                char child = word2.charAt(j); // Character from the second word (potential child)

                // If the characters are different, it indicates an order.
                if (parent != child) {
                    // Add an edge from parent to child if it doesn't already exist.
                    if (!adjList.get(parent).contains(child)) { // Ensure no duplicate edges
                        adjList.get(parent).add(child); // Add the child to the parent's adjacency list
                        indegree.put(child, indegree.get(child) + 1); // Increment the in-degree of the child
                    }
                    break; // Only consider the first different character between the two words
                }

