                }
            }
        }

        // Topological Sort using BFS.
        Queue<Character> queue = new LinkedList<>(); // Queue for BFS

        // Add all nodes (characters) with an in-degree of 0 to the queue.
        for (Character c : indegree.keySet()) {
            if (indegree.get(c) == 0) {
                queue.offer(c); // Add nodes with indegree 0 to the queue
            }
        }

        StringBuilder result = new StringBuilder(); // Result string to store the sorted characters

        // Process nodes in the queue.
        while (!queue.isEmpty()) {
            char c = queue.poll(); // Dequeue a character
