        for (char nei : adj.get(c)) {
            // If a neighbor is currently being visited, a cycle is detected.
            if (visited.get(nei) == 1) {
                return false; // Cycle detected
            }
            // If a neighbor is unvisited, recursively call DFS on it.
            if (visited.get(nei) == 0) {
                if (!dfs(nei, adj, visited, result)) {
                    return false; // If DFS on the neighbor detects a cycle, propagate the failure.
                }
            }
        }

        visited.put(c, 2);     // Mark the current character as 'visited' (completed).
        result.insert(0, c);   // Prepend the character to the result (topological sort order).
        return true;            // No cycle detected from this character.
    }

