        // Build the graph by comparing adjacent words.
        for (int i = 0; i < words.length - 1; i++) {
            String w1 = words[i];
            String w2 = words[i + 1];
            int minLen = Math.min(w1.length(), w2.length()); // Determine the length up to which the words need to be compared.
            boolean foundDiff = false;                     // Flag to indicate if a difference has been found between the words.

            // Compare characters at each position.
            for (int j = 0; j < minLen; j++) {
                if (w1.charAt(j) != w2.charAt(j)) {
                    adj.get(w1.charAt(j)).add(w2.charAt(j)); // Add an edge from the character in w1 to the character in w2.
                    foundDiff = true;                        // Mark that a difference has been found.
                    break;                                   // Only the first difference matters for determining the order.
                }
            }

            // Invalid prefix case: If w1 is a prefix of w2, it's valid. Otherwise, it's invalid.
            if (!foundDiff && w1.length() > w2.length()) {
