function orangesRotting(grid: number[][]): number {
    const queue: [number, number][] = [];
    let fresh = 0;
    let time = 0;

    const ROWS = grid.length;
    const COLS = grid[0].length;

    // Initial scan: count fresh oranges and add initial rotten oranges to the queue
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            if (grid[r][c] === 1) {
                fresh++;
            } else if (grid[r][c] === 2) {
                queue.push([r, c]);
            }
        }
    }

    // Define 4-directional movement vectors
    const directions = [
        [0, 1],   // Right
        [0, -1],  // Left
        [1, 0],   // Down
        [-1, 0],  // Up
    ];

    // BFS loop: continues as long as there are rotten oranges to process and fresh oranges remaining
    while (queue.length > 0 && fresh > 0) {
        // Process all oranges that became rotten in the previous minute (current level)
        const size = queue.length;

        for (let i = 0; i < size; i++) {
            const [r, c] = queue.shift()!;

            // Check all 4 neighbors
            for (const [dr, dc] of directions) {
                const row = r + dr;
                const col = c + dc;

                // Validate neighbor: must be within grid bounds and be a fresh orange
                if (
                    row < 0 ||
                    row >= ROWS ||
                    col < 0 ||
                    col >= COLS ||
                    grid[row][col] !== 1
                ) {
                    continue; // Skip invalid or non-fresh cells
                }

                // Rot the fresh orange
                grid[row][col] = 2;
                queue.push([row, col]); // Add to queue for next minute's processing
                fresh--; // Decrement fresh orange count
            }
        }

        // One minute has passed after processing all oranges from the current level
        time++;
    }

    // Final check: if all fresh oranges rotted, return time; otherwise, return -1
    return fresh === 0 ? time : -1;
}

