        for (int r = 0; r < ROWS; ++r) {
            for (int c = 0; c < COLS; ++c) {
                if (grid[r][c] == 1) {
                    fresh++;
                } else if (grid[r][c] == 2) {
                    q.push({r, c});
                }
            }
        }

        // Directions for 4-directional adjacency
        vector<vector<int>> directions = {
            {0, 1},
            {0, -1},
            {1, 0},
            {-1, 0}
        };

        // Perform BFS level by level
        // Continue as long as there are rotten oranges to spread from AND fresh oranges remain
        while (!q.empty() && fresh > 0) {
            int size = q.size(); // Number of oranges that rotted in the previous minute

            // Process all oranges at the current level (minute)
            for (int i = 0; i < size; ++i) {
                pair<int, int> current = q.front();
                q.pop();
                int r = current.first;
                int c = current.second;

                // Check all 4 adjacent cells
                for (const auto& dir : directions) {
                    int row = r + dir[0];
                    int col = c + dir[1];

                    // Check bounds and if it's a fresh orange
                    if (row >= 0 && row < ROWS && col >= 0 && col < COLS && grid[row][col] == 1) {
                        grid[row][col] = 2; // Mark as rotten
                        q.push({row, col}); // Add to queue for next minute
                        fresh--;           // Decrement fresh count
                    }
                }
            }
            time++; // One minute has passed after processing a level
        }

        // If all fresh oranges rotted, return time, else -1
        return fresh == 0 ? time : -1;
    }
};

