function combinationSum2(candidates: number[], target: number): number[][] {
    // Initialize the result array to store the combinations.
    const result: number[][] = [];

    // Sort the candidates array in ascending order. This is crucial for skipping duplicate combinations.
    candidates.sort((a, b) => a - b);

    // Define the depth-first search (DFS) function.
    function dfs(
        i: number, // Current index in the candidates array.
        current: number[], // Current combination being built.
        total: number // Current sum of the combination.
    ): void {
        // Base case: If the current sum equals the target, add the combination to the result.
        if (total === target) {
            result.push([...current]); // Push a copy of the current combination to avoid modification.
            return;
        }

        // Base case: If the current sum exceeds the target or we've reached the end of the candidates array, backtrack.
        if (total > target || i === candidates.length) {
            return;
        }

        // Include candidates[i] in the current combination.
        current.push(candidates[i]);
        dfs(i + 1, current, total + candidates[i]); // Recurse with the updated sum and the next index.
        current.pop(); // Backtrack: Remove candidates[i] from the current combination.

        // Skip duplicate numbers to avoid duplicate combinations.
        while (
            i + 1 < candidates.length &&
            candidates[i] === candidates[i + 1]
        ) {
            i++; // Increment i to skip the duplicate.
        }

        // Exclude candidates[i] from the current combination.
        dfs(i + 1, current, total); // Recurse with the same sum and the next index.
    }

    // Start the DFS from the beginning of the candidates array with an empty combination and a sum of 0.
    dfs(0, [], 0);
    return result; // Return the result array containing all unique combinations.
}

