function solution(nums: number[], L: number, R: number): number {
  // Given an array nums and a range [L, R], find the minimum value within that range.

  const n = nums.length;
  // Calculate k, which is the floor of the base-2 logarithm of n.  This determines the size of the sparse table.
  const k = Math.floor(log2(n));

  // Initialize the sparse table.  st[i][j] will store the minimum value in the subarray starting at index i with length 2^j.
  const st: number[][] = Array.from({ length: n }, () => new Array(k + 1).fill(0));

  // Initialize the first column of the sparse table with the input array values.
  // This is the base case where the range size is 2^0 = 1.
  for (let i = 0; i < n; i++) {
    st[i][0] = nums[i];
  }

  // Build the sparse table using dynamic programming.
  // For each column j (representing range size 2^j)...
  for (let j = 1; j <= k; j++) {
    // ...and for each row i (representing the starting index of the range)...
    for (let i = 0; i + (1 << j) <= n; i++) {
      // The minimum value in the range [i, i + 2^j - 1] is the minimum of the ranges
      // [i, i + 2^(j-1) - 1] and [i + 2^(j-1), i + 2^j - 1].
      st[i][j] = Math.min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
  }

  // Calculate the length of the query range.
  const len = R - L + 1;
  // Find the largest power of 2 that is less than or equal to the length of the range.
  const j = Math.floor(log2(len));

  // The minimum value in the range [L, R] is the minimum of the ranges
  // [L, L + 2^j - 1] and [R - 2^j + 1, R].  These ranges may overlap, but the minimum is still correct.
  return Math.min(st[L][j], st[R - (1 << j) + 1][j]);
}

