function pacificAtlantic(heights: number[][]): number[][] {
    // Get the dimensions of the grid.
    const ROWS = heights.length;
    const COLS = heights[0].length;

    // Use sets to keep track of which cells can reach the Pacific and Atlantic oceans.
    const pac = new Set<string>();
    const atl = new Set<string>();

    // Depth-First Search function to explore cells reachable from a given starting point.
    function dfs(r: number, c: number, visit: Set<string>, prevHeight: number) {
        // Create a unique key for the cell to store in the set.
        const key = `${r},${c}`;

        // Base cases for DFS:
        // 1. If the cell has already been visited, return.
        // 2. If the cell is out of bounds, return.
        // 3. If the cell's height is less than the previous height (water cannot flow uphill), return.
        if (
            visit.has(key) ||
            r < 0 || c < 0 || r >= ROWS || c >= COLS ||
            heights[r][c] < prevHeight
        ) {
            return;
        }

        // Mark the current cell as visited.
        visit.add(key);

        // Recursively explore neighboring cells (up, down, left, right).
        dfs(r + 1, c, visit, heights[r][c]);
        dfs(r - 1, c, visit, heights[r][c]);
        dfs(r, c + 1, visit, heights[r][c]);
        dfs(r, c - 1, visit, heights[r][c]);
    }

    // Iterate over the top and bottom rows to start DFS from the Pacific and Atlantic oceans.
    for (let c = 0; c < COLS; c++) {
        dfs(0, c, pac, heights[0][c]); // Pacific Ocean (top row)
        dfs(ROWS - 1, c, atl, heights[ROWS - 1][c]); // Atlantic Ocean (bottom row)
    }

    // Iterate over the left and right columns to start DFS from the Pacific and Atlantic oceans.
    for (let r = 0; r < ROWS; r++) {
        dfs(r, 0, pac, heights[r][0]); // Pacific Ocean (left column)
        dfs(r, COLS - 1, atl, heights[r][COLS - 1]); // Atlantic Ocean (right column)
    }

    // Initialize the result array to store the coordinates of cells reachable from both oceans.
    const res: number[][] = [];

    // Iterate over all cells in the grid.
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            // Create a unique key for the cell.
            const key = `${r},${c}`;
            // If the cell is reachable from both the Pacific and Atlantic oceans, add its coordinates to the result array.
            if (pac.has(key) && atl.has(key)) {
                res.push([r, c]);
            }
        }
    }

    // Return the result array.
    return res;
}

