public static class Solution {
    public int swimInWater(int[][] grid) {
        int N = grid.length;

        // PriorityQueue stores int[] {time, row, col}
        // It orders elements based on 'time' (the first element),
        // ensuring we always process the cell reachable with the minimum maximum elevation so far.
        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));

        // Keep track of visited cells to avoid redundant processing and cycles.
        boolean[][] visited = new boolean[N][N];

        // Start at (0,0). The initial time required is its own elevation.
        minHeap.offer(new int[]{grid[0][0], 0, 0});
        visited[0][0] = true;

        // Define possible 4-directional movements: right, left, down, up.
        int[][] directions = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        while (!minHeap.isEmpty()) {
            // Extract the cell with the smallest 'time' (max elevation on path to it) encountered so far.
            int[] current = minHeap.poll();
            int t = current[0]; // Current maximum elevation on path to (r,c)
            int r = current[1]; // Current row
            int c = current[2]; // Current column

            // If we have reached the bottom-right cell, 't' is the minimum time needed.
            if (r == N - 1 && c == N - 1) {
                return t;
            }

            // Explore all 4-directionally adjacent neighbors.
            for (int[] dir : directions) {
                int nr = r + dir[0]; // Next row
                int nc = c + dir[1]; // Next column

                // Check for valid boundaries and if the cell has already been visited.
                if (nr >= 0 && nr < N && nc >= 0 && nc < N && !visited[nr][nc]) {
                    // Mark the new cell as visited.
                    visited[nr][nc] = true;

                    // The time required to reach (nr, nc) is the maximum of:
                    // 1. The current maximum elevation encountered on the path to (r, c) ('t').
                    // 2. The elevation of the new cell (grid[nr][nc]).
                    // This ensures the water level is high enough for *all* cells on the path including (nr, nc).
                    minHeap.offer(new int[]{Math.max(t, grid[nr][nc]), nr, nc});
                }
            }
        }

        // This line should theoretically not be reached if a path always exists (guaranteed by problem constraints).
        return -1;
    }
}

