class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        int N = grid.size();

        // Min-priority queue: stores tuples of (time, row, col)
        // The 'greater' comparator makes it a min-heap based on the first element (time).
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> minHeap;

        // Visited array to keep track of processed cells
        // Using a 2D boolean array for efficiency with grid coordinates
        vector<vector<bool>> visited(N, vector<bool>(N, false));

        // Directions for 4-directional movement (right, left, down, up)
        vector<vector<int>> directions = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        // Start at (0,0). The initial 'time' required is its own elevation.
        minHeap.push({grid[0][0], 0, 0});
        visited[0][0] = true;

        while (!minHeap.empty()) {
            // Extract the cell with the minimum maximum elevation encountered so far
            auto [t, r, c] = minHeap.top();
            minHeap.pop();

            // If we've reached the bottom-right cell, this 't' is our answer
            if (r == N - 1 && c == N - 1) {
                return t;
            }

            // Explore neighbors
            for (const auto& dir : directions) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Check boundary conditions and if the neighbor has been visited
                if (nr < 0 || nc < 0 || nr >= N || nc >= N || visited[nr][nc]) {
                    continue;
                }

                // Mark the neighbor as visited
                visited[nr][nc] = true;

                // The time required to reach (nr, nc) via (r, c) is the maximum
                // of the current path's maximum elevation ('t') and the elevation
                // of the new cell ('grid[nr][nc]').
                int newTime = max(t, grid[nr][nc]);

                // Add the neighbor to the priority queue with its calculated time
                minHeap.push({newTime, nr, nc});
            }
        }

        // Should not be reached if a path always exists (as per problem constraints where N >= 1)
        return -1;
    }
};

