function findItinerary(tickets: string[][]): string[] {
    const adj: Record<string, string[]> = {};

    // Initialize adjacency list for all source airports.
    // This ensures all potential starting points for flights have an entry,
    // even if temporarily empty before actual destinations are added.
    for (const [src] of tickets) {
        adj[src] = [];
    }

    // Sort tickets to ensure lexicographical order. If source airports are the same,
    // sort by destination airport. This greedy approach helps find the
    // smallest lexical itinerary first during DFS.
    tickets.sort((a, b) => {
        if (a[0] === b[0]) {
            return a[1].localeCompare(b[1]);
        }
        return a[0].localeCompare(b[0]);
    });

    // Populate the adjacency list. Since tickets are sorted, the destination lists
    // (e.g., adj["JFK"]) will inherently store destinations in lexical order.
    for (const [src, dst] of tickets) {
        adj[src].push(dst);
    }

    const result: string[] = ["JFK"]; // The itinerary must start from "JFK".

    // Depth-First Search (DFS) function with backtracking.
    // It attempts to build a valid itinerary using all tickets.
    function dfs(src: string): boolean {
        // Base case: If the itinerary length is tickets.length + 1,
        // it means all tickets have been used exactly once.
        if (result.length === tickets.length + 1) {
            return true; // Found a complete itinerary.
        }

        // If the current source airport has no outgoing flights (either never had any
        // or all have been used up in this path) and we still need to use tickets,
        // this path is invalid. Note: 'src in adj' would be false if src was never a source.
        // If src was a source but now adj[src] is empty, the loop below handles it.
        if (!(src in adj)) {
             return false;
        }

        // Create a temporary copy of the current available flights from 'src'.
        // This is crucial because we modify adj[src] (splice) during iteration,
        // and iterating directly over adj[src] would lead to skipped elements
        // or incorrect indices upon backtracking.
        const temp = [...adj[src]];

        // Iterate through possible next destinations from 'src'.
        // Because of prior sorting, these destinations are already in lexical order.
        for (let i = 0; i < temp.length; i++) {
            const next = temp[i];

            // CHOOSE: Mark the ticket as used and add to the itinerary.
            adj[src].splice(i, 1); // Remove the flight from available options.
            result.push(next);     // Add destination to the current itinerary.

            // EXPLORE: Recursively call DFS for the next airport.
            if (dfs(next)) {
                return true; // If a valid itinerary is found, propagate success.
            }

            // UNCHOOSE (BACKTRACK): If the recursive call didn't find a solution,
            // revert the changes to explore other paths.
            adj[src].splice(i, 0, next); // Add the flight back to available options.
            result.pop();               // Remove the destination from the itinerary.
        }

        return false; // No valid path found from this 'src' with remaining tickets.
    }

    // Start the DFS from "JFK". The problem guarantees a valid itinerary exists.
    dfs("JFK");

    return result;
}

