            String next = destinations.get(i);

            // --- Make a Choice: Use the ticket (src -> next) ---
            // Remove the ticket from the available flights list.
            // The 'remove(i)' operation on an ArrayList shifts subsequent elements, taking O(degree) time.
            adj.get(src).remove(i);
