            result.add(next);

            // --- Recurse: Try to complete the rest of the itinerary from the 'next' airport ---
            if (dfs(next)) {
                return true; // If the recursive call found a complete itinerary, propagate success upwards.
            }

            // --- Backtrack: If the recursive call failed (i.e., didn't lead to a full itinerary) ---
            // Restore the ticket to the available flights list at its original position 'i'.
            // The 'add(i, element)' operation on an ArrayList shifts subsequent elements, taking O(degree) time.
            adj.get(src).add(i, next);
            // Remove the 'next' airport from our itinerary path, undoing the choice.
