            adj[ticket[0]].push_back(ticket[1]);
        }

        // Start DFS from JFK, as the itinerary must begin there.
        result.push_back("JFK");
        dfs("JFK");

        return result;
    }

      bool dfs(string src) {
        // Base case: If we have used all tickets + 1 (start) airport in our result
        if (result.size() == numTickets + 1) {
            return true;
        }

        // Make a temporary copy of the current source's destinations to iterate.
        // This is crucial because `adj[src]` is modified during iteration (tickets are "used").
        // If `src` is not in `adj` or `adj[src]` is empty, `temp_destinations` will be empty,
        // and the loop below won't execute, correctly leading to `false`.
        vector<string> temp_destinations = adj[src]; // Copy by value

        for (int i = 0; i < temp_destinations.size(); ++i) {
            string next_airport = temp_destinations[i];

            // "Use" the ticket: remove it from the adjacency list.
            // `erase` shifts subsequent elements, taking O(degree) time.
            adj[src].erase(adj[src].begin() + i);
            result.push_back(next_airport);

            // Recurse to the next airport
            if (dfs(next_airport)) {
                return true; // Found a valid itinerary
            }

            // Backtrack: if the recursive call didn't find a solution,
            // put the ticket back and remove the airport from the result.
            // `insert` shifts subsequent elements, taking O(degree) time.
            adj[src].insert(adj[src].begin() + i, next_airport);
            result.pop_back();
        }

        return false; // No valid path found from this source with remaining tickets
    }
