function longestIncreasingPath(matrix: number[][]): number {
    const ROWS = matrix.length;
    const COLS = matrix[0].length;

    const dp = new Map<string, number>();

    function dfs(r: number, c: number, prevVal: number): number {
        // Base cases: out of bounds, or current cell value is not strictly greater than previous
        if (
            r < 0 ||
            r >= ROWS ||
            c < 0 ||
            c >= COLS ||
            matrix[r][c] <= prevVal
        ) {
            return 0;
        }

        // Memoization check: if result for (r, c) is already computed, return it
        const key = `${r},${c}`;
        if (dp.has(key)) {
            return dp.get(key)!;
        }

        // Initialize result for current cell (at least 1, for the cell itself)
        let res = 1;

        // Explore all four directions and take the maximum path length
        // Add 1 to each recursive call's result to account for the current cell
        res = Math.max(res, 1 + dfs(r + 1, c, matrix[r][c])); // Down
        res = Math.max(res, 1 + dfs(r - 1, c, matrix[r][c])); // Up
        res = Math.max(res, 1 + dfs(r, c + 1, matrix[r][c])); // Right
        res = Math.max(res, 1 + dfs(r, c - 1, matrix[r][c])); // Left

        // Store the computed result for (r, c) in the DP map
        dp.set(key, res);
        return res;
    }

    let ans = 0;

    // Iterate through every cell as a potential starting point for an increasing path
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            // Call dfs with prevVal = -1 to allow any matrix value to start a path
            ans = Math.max(ans, dfs(r, c, -1));
        }
    }

    return ans;
}

