function maxPathSum(root: TreeNode | null): number {
    // Initialize the result to negative infinity to handle cases with all negative nodes.
    let res = -Infinity

    // DFS function to calculate the maximum path sum without splitting at the current node.
    function dfs(node: TreeNode | null): number {
        // Base case: if the node is null, return 0 as it contributes nothing to the path sum.
        if (!node) return 0

        // Recursively calculate the maximum path sum from the left and right subtrees.
        let leftMax = dfs(node.left)
        let rightMax = dfs(node.right)

        // If the maximum path sum from a subtree is negative, discard it by setting it to 0.
        // Including a negative path sum will always decrease the overall sum.
        leftMax = Math.max(leftMax, 0)
        rightMax = Math.max(rightMax, 0)

        // Calculate the maximum path sum WITH a split at the current node.
        // This is the case where the path goes through both the left and right subtrees.
        res = Math.max(res, node.val + leftMax + rightMax)

        // Return the maximum path sum WITHOUT a split, which is the current node's value
        // plus the maximum of the left and right subtree path sums.
        // This value is used by the parent node to calculate its maximum path sums.
        return node.val + Math.max(leftMax, rightMax)
    }

    // Start the DFS from the root node.
    dfs(root)
    // Return the overall maximum path sum found.
    return res
}

