            dfs(i + 1, j)
        ) {
            return true;
        }

        if (
            j < s2.length &&
            s2[j] === s3[i + j] &&
            dfs(i, j + 1)
        ) {
            return true;
        }

        dp.set(key, false);
        return false;
    };

    return dfs(0, 0);
}

