    private Boolean[][] memo;

    public boolean isInterleave(String s1, String s2, String s3) {
        if (s1.length() + s2.length() != s3.length()) {
            return false;
        }

        this.s1_ref = s1;
        this.s2_ref = s2;
        this.s3_ref = s3;
        // memo[i][j] stores the result for dfs(i, j)
        // i goes up to s1.length, j goes up to s2.length
        this.memo = new Boolean[s1.length() + 1][s2.length() + 1];

        return dfs(0, 0);
    }

    private boolean dfs(int i, int j) {
        // Base case: If we've used all characters from both s1 and s2,
        // and s3's length matches s1.length + s2.length,
        // it means we successfully formed s3.
        if (i == s1_ref.length() && j == s2_ref.length()) {
            return true;
        }

        // Check memoization table
        if (memo[i][j] != null) {
            return memo[i][j];
        }

        boolean result = false;

        // Option 1: Try to match current character from s1
        // Check if there are characters remaining in s1 (i < s1_ref.length())
        // AND if the character at s1[i] matches the current character needed for s3 (s3[i+j])
        // AND if the rest of the strings can be interleaved (dfs(i+1, j))
        if (i < s1_ref.length() && s1_ref.charAt(i) == s3_ref.charAt(i + j)) {
            if (dfs(i + 1, j)) {
                result = true;
            }
        }

        // Option 2: If result is still false (meaning option 1 either failed or wasn't taken),
        // try to match current character from s2
        // Check if there are characters remaining in s2 (j < s2_ref.length())
        // AND if the character at s2[j] matches the current character needed for s3 (s3[i+j])
        // AND if the rest of the strings can be interleaved (dfs(i, j+1))
        if (!result && j < s2_ref.length() && s2_ref.charAt(j) == s3_ref.charAt(i + j)) {
            if (dfs(i, j + 1)) {
                result = true;
            }
        }

        // Store the result in the memoization table before returning
        memo[i][j] = result;
        return result;
    }
}

