function maxProfit(prices: number[]): number {
    // If the prices array is null or has fewer than 2 elements, no profit can be made.
    if (!prices || prices.length <= 1) {
        return 0;
    }

    // n stores the number of days (length of the prices array).
    const n = prices.length;

    // buy[i] stores the maximum profit if we buy on or before day i.
    const buy = new Array(n).fill(0);

    // sell[i] stores the maximum profit if we sell on or before day i.
    const sell = new Array(n).fill(0);

    // cooldown[i] stores the maximum profit if we cooldown on or before day i.
    const cooldown = new Array(n).fill(0);

    // Initialize the base case for the first day.
    // On day 0, if we buy, the profit is -prices[0].
    buy[0] = -prices[0];
    // On day 0, if we cooldown, the profit is 0.
    cooldown[0] = 0;
    // On day 0, if we sell, the profit is 0.
    sell[0] = 0;

    // Iterate through the prices array starting from the second day (day 1).
    for (let i = 1; i < n; i++) {
        // The maximum profit on day i if we buy is the maximum of:
        // 1. The profit from cooling down on the previous day and then buying on day i.
        // 2. The profit from the previous day if we already bought (or didn't sell).
        buy[i] = Math.max(cooldown[i - 1] - prices[i], buy[i - 1]);

        // The maximum profit on day i if we sell is the profit from buying on the previous day and then selling on day i.
        sell[i] = buy[i - 1] + prices[i];

        // The maximum profit on day i if we cooldown is the maximum of:
        // 1. The profit from cooling down on the previous day.
        // 2. The profit from selling on the previous day.
        cooldown[i] = Math.max(cooldown[i - 1], sell[i - 1]);
    }

    // The maximum profit is the maximum of the profit from selling on the last day and cooling down on the last day.
    return Math.max(sell[n - 1], cooldown[n - 1]);
}

