    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        if (n == 0) return 0; // If no prices are given, there's no profit to be made.

        // buy[i]: Max profit at day i if holding a stock (just bought or held from yesterday).
        // sell[i]: Max profit at day i if selling a stock today.
        // cooldown[i]: Max profit at day i if in cooldown state (cannot buy today).
        vector<int> buy(n, 0);
        vector<int> sell(n, 0);
        vector<int> cooldown(n, 0);

        // On day 0, we can only buy the stock (resulting in a negative profit).
        buy[0] = -prices[0];

        // Iterate from day 1 to the last day.
        for (int i = 1; i < n; ++i) {
            // buy[i] can be achieved by either:
            // 1. Holding the stock from yesterday: buy[i - 1]
            // 2. Buying the stock today after being in cooldown yesterday: cooldown[i - 1] - prices[i]
            buy[i] = max(buy[i - 1], cooldown[i - 1] - prices[i]);

            // sell[i] can be achieved only by selling the stock that we were holding yesterday: buy[i - 1] + prices[i]
            sell[i] = buy[i - 1] + prices[i];

            // cooldown[i] can be achieved by either:
            // 1. Being in cooldown from yesterday: cooldown[i - 1]
            // 2. Selling the stock yesterday: sell[i - 1]
            // 3. Still holding stock from yesterday, but could sell today, so consider it in cooldown: buy[i-1]
            cooldown[i] = max({cooldown[i - 1], sell[i - 1], buy[i-1]});
        }

        // The maximum profit at the end can be either from being in cooldown or selling the stock on the last day, or still holding it.
        return max({cooldown[n - 1], sell[n - 1], buy[n-1]});
