function multiply(num1: string, num2: string): string {
    // Step 1: Handle edge cases where one or both numbers are "0".
    // If either input string represents the number zero, their product is always "0".
    if (num1 === "0" || num2 === "0") {
        return "0";
    }

    // Step 2: Initialize a result array to store the digits of the product.
    // The maximum possible length for the product of two numbers with lengths M and N is M + N.
    // For example, 99 * 99 = 9801 (lengths 2 + 2 = 4).
    // This array will hold the digits of our result, initially filled with zeros.
    // We will accumulate digits from right to left, so the least significant digit
    // will be at index 0 initially (before final reversal).
    const res = new Array(num1.length + num2.length).fill(0);

    // Step 3: Prepare input strings for easier processing.
    // Convert num1 and num2 into arrays of individual digits.
    // Reverse these arrays to facilitate multiplication from right to left (least significant digit first),
    // which mirrors how we perform manual long multiplication.
    const n1 = num1.split("").reverse();
    const n2 = num2.split("").reverse();

    // Step 4: Perform digit-by-digit multiplication and handle carries.
    // Iterate through each digit of the first reversed number (n1).
    for (let i = 0; i < n1.length; i++) {
        // Iterate through each digit of the second reversed number (n2).
        for (let j = 0; j < n2.length; j++) {
            // Convert characters back to numbers and calculate the product of the current digits.
            // n1[i] corresponds to the (i)-th digit from the right of the original num1.
            // n2[j] corresponds to the (j)-th digit from the right of the original num2.
            const digitProduct = Number(n1[i]) * Number(n2[j]);

            // Add the 'digitProduct' to the current position in the 'res' array.
            // The position 'i + j' correctly corresponds to the place value of this partial product.
            // For example, if n1[0] (units) * n2[0] (units), result goes to res[0] (units place).
            // If n1[1] (tens) * n2[0] (units), result goes to res[1] (tens place).
            res[i + j] += digitProduct;

            // Calculate and propagate the carry-over.
            // The carry from `res[i + j]` (e.g., if res[i+j] becomes 15, carry is 1) is added
            // to the next higher place value, which is `res[i + j + 1]`.
            res[i + j + 1] += Math.floor(res[i + j] / 10);

            // Update the current position `res[i + j]` to retain only its units digit.
            // This ensures that `res[i + j]` holds the correct single digit for its place value.
            res[i + j] %= 10;
        }
    }

    // Step 5: The 'res' array currently stores digits in reverse order (least significant digit at index 0).
    // Reverse the array to get the digits in the correct, most-significant-digit-first order.
    res.reverse();

    // Step 6: Remove any leading zeros from the result.
    // For example, a product might result in `[0, 0, 1, 2, 3]`. We need to remove the initial zeros.
    let start = 0;
    while (start < res.length && res[start] === 0) {
        start++;
    }

    // If 'start' equals 'res.length', it means all digits were zero.
    // This case should ideally be covered by the initial edge case check (e.g., "0" * "5").
    // However, if it could somehow happen that `res` becomes `[0]` and we didn't handle it,
    // this would result in an empty array `[]` after slicing. But `0` is already returned.
    // Slice the array from the first non-zero digit found (or from the end if all zeros).
    // Join the remaining digits to form the final product string.
    return res.slice(start).join("");
}

