                // This includes any pre-existing value from previous multiplications that contributed here
                // (e.g., from a prior carry or a sum from another digit multiplication ending at this spot),
                // plus the new 'product' itself.
                // The position (i + j + 1) in the 'res' array corresponds to the units place of the current product.
                int sum = res[i + j + 1] + product;

