function change(amount: number, coins: number[]): number {
    // dp[i][j] represents the number of combinations to make amount 'i' using coins[j...n]
    const dp: number[][] = Array.from(
        { length: amount + 1 },
        () => Array(coins.length + 1).fill(0)
    );

    // Base case: If amount is 0, there is 1 way to make it (using no coins)
    dp[0] = Array(coins.length + 1).fill(1);

    // Iterate through all amounts from 1 to 'amount'
    for (let a = 1; a <= amount; a++) {
        // Iterate through coins array from the end to beginning to avoid permutations.
        for (let i = coins.length - 1; i >= 0; i--) {
            // dp[a][i] is initially the number of ways to make amount 'a' using coins[i+1...n]
            dp[a][i] = dp[a][i + 1];

            // If the current coin value is less than or equal to the current amount,
            // we add the number of ways to make the remaining amount (a - coins[i]) using coins[i...n].
            if (a - coins[i] >= 0) {
                dp[a][i] += dp[a - coins[i]][i];
            }
        }
    }

    // The result is the number of combinations to make 'amount' using coins[0...n]
    return dp[amount][0];
}

