function minWindow(s: string, t: string): string {
    // If t is an empty string, return an empty string.
    if (t === "") return "";

    // countT will store the frequency of each character in t.
    const countT: Record<string, number> = {};
    // window will store the frequency of each character in the current window of s.
    const window: Record<string, number> = {};

    // Count frequency of characters in t.
    for (const c of t) {
        countT[c] = (countT[c] || 0) + 1;
    }

    // have will track how many characters in the window have met the required frequency in t.
    let have = 0;
    // need is the number of unique characters in t that we need to find in the window.
    const need = Object.keys(countT).length;

    // res will store the start and end indices of the minimum window substring.
    let res: [number, number] = [-1, -1];
    // resLen will store the length of the minimum window substring.
    let resLen = Infinity;

    // l is the left pointer of the sliding window.
    let l = 0;

    // Iterate through the string s with the right pointer r.
    for (let r = 0; r < s.length; r++) {
        const c = s[r];

        // Expand the window by adding the character s[r] to the window.
        window[c] = (window[c] || 0) + 1;

        // If the current character is in t and its frequency in the window matches its frequency in t,
        // increment have.
        if (c in countT && window[c] === countT[c]) {
            have++;
        }

        // Try to shrink the window as much as possible while still maintaining the condition that
        // the window contains all characters in t with the required frequencies.
        while (have === need) {
            // Update result if a smaller window is found.
            if ((r - l + 1) < resLen) {
                res = [l, r];
                resLen = r - l + 1;
            }

            // Remove the leftmost character from the window.
            const leftChar = s[l];
            window[leftChar]--;

            // If the removed character is in t and its frequency in the window is now less than its frequency in t,
            // decrement have.
            if (leftChar in countT && window[leftChar] < countT[leftChar]) {
                have--;
            }

            // Move the left pointer to the right.
            l++;
        }
    }

    // Extract the result.
    const [start, end] = res;
    // If resLen is still Infinity, it means no valid window was found, so return an empty string.
    // Otherwise, return the substring of s from start to end (inclusive).
    return resLen !== Infinity ? s.slice(start, end + 1) : "";
}

