function reverse(x: number): number {
    const MIN = -(2 ** 31);
    const MAX = 2 ** 31 - 1;

    let res = 0;

    while (x !== 0) {
        const digit = x % 10;
        x = Math.trunc(x / 10);

        // Check for potential overflow for positive numbers
        // If res is already greater than MAX / 10, then res * 10 will definitely overflow.
        // If res is equal to MAX / 10, adding a digit greater than MAX % 10 will overflow.
        if (
            res > Math.trunc(MAX / 10) ||
            (res === Math.trunc(MAX / 10) && digit > MAX % 10)
        ) {
            return 0;
        }

        // Check for potential underflow for negative numbers
        // If res is already less than MIN / 10, then res * 10 will definitely underflow.
        // If res is equal to MIN / 10, adding a digit less than MIN % 10 will underflow.
        if (
            res < Math.trunc(MIN / 10) ||
            (res === Math.trunc(MIN / 10) && digit < MIN % 10)
        ) {
            return 0;
        }

        res = res * 10 + digit;
    }

    return res;
}

