function generateParenthesis(n: number): string[] {
    const stack: string[] = [];
    const result: string[] = [];

    const backtrack = (openN: number, closedN: number): void => {
        // Base case: If we have placed 'n' open and 'n' closed parentheses,
        // then a valid combination is formed.
        if (openN === n && closedN === n) {
            result.push(stack.join(""));
            return;
        }

        // Recursive Step 1: Add an open parenthesis if we haven't reached 'n' open ones yet.
        // This ensures we always have enough opening brackets to potentially close.
        if (openN < n) {
            stack.push("(");
            backtrack(openN + 1, closedN);
            stack.pop(); // Backtrack: remove the last added '(' to explore other paths
        }

        // Recursive Step 2: Add a closed parenthesis if it forms a well-formed pair.
        // This means the number of closed parentheses must be less than the number of open ones.
        if (closedN < openN) {
            stack.push(")");
            backtrack(openN, closedN + 1);
            stack.pop(); // Backtrack: remove the last added ')'
        }
    };

    // Start the backtracking process from zero open and zero closed parentheses.
    backtrack(0, 0);
    return result;
}

