function reverseBetween(
    head: ListNode | null,
    left: number,
    right: number
): ListNode | null {
    // Create a dummy node to simplify edge cases, especially when left = 1
    // The dummy node's next points to the head of the original list.
    const dummy = new ListNode(0, head);

    // 1) Reach the node at position "left" (or rather, the node *before* it)
    // 'leftPrev' will point to the node immediately preceding the segment to be reversed.
    // 'cur' will point to the *start* of the segment to be reversed (the 'left'-th node).
    let leftPrev: ListNode = dummy;
    let cur: ListNode | null = head;

    // Traverse (left - 1) steps to position 'leftPrev' and 'cur'.
    // If left = 1, this loop doesn't run. 'leftPrev' remains 'dummy', and 'cur' remains 'head'.
    for (let i = 0; i < left - 1; i++) {
        leftPrev = cur!;
        cur = cur!.next;
    }

    // At this point:
    // 'leftPrev' is the node immediately preceding the segment [left, right].
    // 'cur' is the 'left'-th node, which is the head of the segment to be reversed.
    // Note: 'leftPrev.next' still points to 'cur' initially, and 'cur' is the original 'left'-th node.

    // 2) Reverse the sublist from 'left' to 'right'
    // 'prev' will be used to build the reversed segment. It will ultimately become
    // the new head of the reversed segment (i.e., the original 'right'-th node).
    // 'cur' will continue advancing during the reversal, and after the loop, it will
    // point to the node immediately *after* the original 'right'-th node.
    let prev: ListNode | null = null;

    // Loop (right - left + 1) times to reverse the nodes within the specified segment.
    // The original 'cur' (the 'left'-th node, initially 'leftPrev.next') will become
    // the tail of the reversed segment. Its 'next' pointer will be updated in step 3.
    for (let i = 0; i < right - left + 1; i++) {
        const tmpNext = cur!.next; // Temporarily store the next node
        cur!.next = prev;          // Reverse the current node's pointer to point to the previous node
        prev = cur;                // Move 'prev' to the current node (which is now reversed)
        cur = tmpNext;             // Move 'cur' to the next node (from the original list order)
    }

    // After the reversal loop:
    // 'prev' now points to the original 'right'-th node (this is the new head of the reversed segment).
    // 'cur' now points to the node immediately *after* the original 'right'-th node.
    // 'leftPrev' still points to the node before the reversed segment (e.g., '1' in [1,2,3,4,5], 2, 4).

    // 3) Update pointers to reconnect the reversed segment to the rest of the list
    // The node that was originally at 'left' (which is 'leftPrev.next' *before* the next line executes)
    // now serves as the tail of the reversed segment. Its 'next' pointer should point
    // to the node that comes immediately *after* the original 'right'-th node, which is 'cur'.
    leftPrev.next!.next = cur; // Connect the tail of the reversed segment to the node after 'right'

    // The node immediately preceding the reversed segment ('leftPrev') should now point
    // to the new head of the reversed segment, which is 'prev'.
    leftPrev.next = prev;      // Connect the node before 'left' to the new head of the reversed segment

    return dummy.next; // Return the head of the modified list. If left=1, dummy.next will be the new head.
}

