function canFinish(numCourses: number, prerequisites: number[][]): boolean {
  // If there are no prerequisites, we can finish all courses.
  if (prerequisites.length === 0) return true;

  // Initialize the adjacency list to represent the graph.
  const adjList: number[][] = Array(numCourses).fill(null).map(() => []);
  // Initialize the in-degree array to store the in-degree of each course.
  const inDegree: number[] = Array(numCourses).fill(0);

  // Populate the adjacency list and in-degree array based on prerequisites.
  for (const [course, pre] of prerequisites) {
    // 'course' depends on 'pre', so add 'course' to the adjacency list of 'pre'.
    adjList[pre].push(course);
    // Increment the in-degree of 'course' because it has a new prerequisite.
    inDegree[course]++;
  }

  // Initialize a queue to store courses with an in-degree of 0.
  const queue: number[] = [];
  // Add all courses with no prerequisites (in-degree of 0) to the queue.
  for (let i = 0; i < numCourses; i++) {
    if (inDegree[i] === 0) {
      queue.push(i);
    }
  }

  // Initialize a counter to keep track of the number of visited courses.
  let count = 0;
  // Process the queue using Kahn's algorithm.
  while (queue.length > 0) {
    // Get the next course from the queue.
    const course = queue.shift()!;
    // Increment the count of visited courses.
    count++;

    // Iterate over the neighbors (dependent courses) of the current course.
    for (const neighbor of adjList[course]) {
      // Decrement the in-degree of the neighbor.
      inDegree[neighbor]--;
      // If the neighbor's in-degree becomes 0, add it to the queue.
      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
      }
    }
  }

  // If the number of visited courses equals the total number of courses,
  // then we can finish all courses; otherwise, there is a cycle.
  return count === numCourses;
}

public static class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        // If there are no prerequisites, we can finish all courses.
        if (prerequisites == null || prerequisites.length == 0) {
            return true;
        }

        // indegree[i] stores the number of prerequisites for course i
        int[] indegree = new int[numCourses];
        // adjList is an adjacency list representing the graph
        List<List<Integer>> adjList = new ArrayList<>();
        // Initialize the adjacency list
        for (int i = 0; i < numCourses; i++) {
            adjList.add(new ArrayList<>());
        }

        // Populate the adjacency list and indegree array
        for (int[] prerequisite : prerequisites) {
            int course = prerequisite[0]; // Course to take
            int pre = prerequisite[1];    // Prerequisite course
            adjList.get(pre).add(course); // Add 'course' to the list of courses that depend on 'pre'
            indegree[course]++;            // Increment the indegree of 'course'
        }

        // Queue to store courses with indegree of 0 (no prerequisites)
        Queue<Integer> queue = new LinkedList<>();
        // Add all courses with no prerequisites to the queue
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        // Counter to keep track of the number of visited courses
        int count = 0;
        // Process the queue until it's empty
        while (!queue.isEmpty()) {
            int course = queue.poll(); // Get the next course from the queue
            count++;                    // Increment the count of visited courses

            // Iterate over the neighbors (dependent courses) of the current course
            for (int neighbor : adjList.get(course)) {
                indegree[neighbor]--; // Decrement the indegree of the neighbor
                // If the neighbor's indegree becomes 0, add it to the queue
                if (indegree[neighbor] == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        // If the number of visited courses equals the total number of courses,
        // then we can finish all courses; otherwise, there is a cycle
        return count == numCourses;
    }
}

