function findMedianSortedArrays(nums1: number[], nums2: number[]): number {
    let A = nums1;
    let B = nums2;

    const total = A.length + B.length;
    const half = Math.floor(total / 2);

    // Ensure A is the shorter array. This optimizes the binary search space,
    // making the complexity O(log(min(m, n))). If B is shorter, swap them.
    if (B.length < A.length) {
        [A, B] = [B, A]; // Swap arrays using destructuring assignment
    }

    // Binary search range for partition 'i' in array A.
    // 'l' and 'r' define the possible indices for the rightmost element of A's left partition.
    // `l = 0` implies A[0] could be the first element, `r = A.length - 1` implies A[A.length-1] could be the last.
    let l = 0;
    let r = A.length - 1;

    while (true) {
        // 'i' is the potential index for the rightmost element of A's left partition.
        // Its range effectively represents the count of elements taken from A's left part.
        // If i = -1, means 0 elements from A's left. If i = A.length-1, means all elements from A's left.
        const i = Math.floor((l + r) / 2);

        // 'j' is the corresponding index for B's left partition.
        // The total number of elements in the combined left partition should be `Math.ceil(total / 2)`.
        // With 'i' and 'j' being indices of the rightmost elements in their respective left partitions,
        // the number of elements from A is `i+1`, and from B is `j+1`.
        // So, `(i+1) + (j+1) = Math.ceil(total / 2)`.
        // A common implementation for `j` (which works for this indexing scheme) is `half - i - 2`.
        // This `half` (floor(total/2)) and `i` (index) definition leads to `j` (index) that correctly splits `B`.
        const j = half - i - 2;            

        // Get the values at the partition boundaries, handling edge cases with -Infinity and Infinity.
        // Aleft: The rightmost element of A's left partition. If `i` is -1 (conceptually no elements from A),
        // it's treated as -Infinity to ensure it doesn't violate the partition condition.
        const Aleft = i >= 0 ? A[i] : -Infinity;
        // Aright: The leftmost element of A's right partition. If `i+1` is out of bounds (all A elements in left),
        // it's treated as Infinity.
        const Aright = i + 1 < A.length ? A[i + 1] : Infinity;

        // Bleft: The rightmost element of B's left partition. Similar edge case handling for `j`.
        const Bleft = j >= 0 ? B[j] : -Infinity;
        // Bright: The leftmost element of B's right partition. Similar edge case handling for `j+1`.
        const Bright = j + 1 < B.length ? B[j + 1] : Infinity;

        // Check if the partition is correct.
        // A correct partition means: max(elements in left half) <= min(elements in right half).
        // This translates to two conditions: Aleft <= Bright AND Bleft <= Aright.
        if (Aleft <= Bright && Bleft <= Aright) {
            // Partition is valid, calculate the median.

            // If total length is odd, the median is the single middle element.
            // This element is the smallest element in the combined right partition.
            if (total % 2) {
                return Math.min(Aright, Bright);
            }

            // If total length is even, the median is the average of the two middle elements.
            // These are the largest element in the combined left partition (max(Aleft, Bleft))
            // and the smallest element in the combined right partition (min(Aright, Bright)).
            return (
                (Math.max(Aleft, Bleft) + Math.min(Aright, Bright)) / 2
            );
        } else if (Aleft > Bright) {
            // If Aleft is greater than Bright, it means A's left partition contains elements
            // that are too large (i.e., `i` is too far to the right in A).
            // We need to move the partition in A to the left to include smaller elements.
            r = i - 1;
        } else {
            // If Bleft is greater than Aright, it means B's left partition contains elements
            // that are too large (i.e., `j` is too far to the right in B, or `i` is too far left in A).
            // We need to move the partition in A to the right to balance B's larger elements.
            l = i + 1;
        }
    }
}

