    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        // Assign nums1 and nums2 to A and B for consistency and readability.
        int[] A = nums1;
        int[] B = nums2;

        // Get the lengths of the arrays.
        int m = A.length;
        int n = B.length;

        // Optimization: Ensure array A is always the shorter one.
        // This significantly reduces the search space for the binary search,
        // guaranteeing a time complexity of O(log(min(m, n))). If A is longer,
        // we swap A and B, along with their lengths.
        if (m > n) {
            int[] temp = A;
            A = B;
            B = temp;

            int tempLen = m;
            m = n;
            n = tempLen;
        }

        // Calculate the total number of elements in the combined array.
        // This determines if the median is a single element (odd total length)
        // or the average of two elements (even total length).
        int totalLength = m + n;
        // `halfPartLength` represents the number of elements that should be in the
        // left partition of the combined sorted array. For example:
        // If totalLength = 5, (5+1)/2 = 3. We need 3 elements in the left partition.
        // If totalLength = 4, (4+1)/2 = 2. We need 2 elements in the left partition.
        // This value is crucial for determining `cutB` based on `cutA`.
        int halfPartLength = (totalLength + 1) / 2;

        // Initialize the binary search range for `cutA` (the partition point in array A).
        // `low` can be 0 (meaning 0 elements from A are in the left partition).
        // `high` can be `m` (meaning all `m` elements from A are in the left partition).
        int low = 0;
        int high = m;

        // Perform binary search to find the optimal `cutA`.
        // The loop continues as long as there's a valid search space for `cutA`.
        while (low <= high) {
            // Calculate `cutA`: the partition point in array A.
            // This is a standard way to calculate the mid-point to prevent potential integer overflow.
            // `cutA` signifies that `cutA` elements from array A are included in the left partition
            // and `m - cutA` elements are in the right partition of A.
            int cutA = low + (high - low) / 2;

            // Calculate `cutB`: the partition point in array B.
            // This is derived from `halfPartLength` and `cutA`.
            // The sum `cutA + cutB` must equal `halfPartLength` to ensure the combined
            // left partition has the correct total number of elements.
            // `cutB` signifies that `cutB` elements from array B are included in the left partition
            // and `n - cutB` elements are in the right partition of B.
            int cutB = halfPartLength - cutA;

            // Determine the boundary elements for the partitions.
            // We use `long` to accommodate sentinel values and prevent potential overflow
            // during max/min operations, especially with large inputs or the sentinel values themselves.

            // Aleft: The last element of A's left partition.
            // If `cutA` is 0, it means no elements from A are in the left partition, so we use a very
            // small sentinel value (-10^6-1, which is less than any possible array element).
            // Otherwise, it's A[cutA - 1].
            long Aleft = (cutA == 0) ? -1000001L : A[cutA - 1];

            // Aright: The first element of A's right partition.
            // If `cutA` is `m`, it means all elements from A are in the left partition, so we use a very
            // large sentinel value (10^6+1, which is greater than any possible array element).
            // Otherwise, it's A[cutA].
            long Aright = (cutA == m) ? 1000001L : A[cutA];

            // Bleft: The last element of B's left partition.
            // Similar logic as Aleft, for array B.
            long Bleft = (cutB == 0) ? -1000001L : B[cutB - 1];

            // Bright: The first element of B's right partition.
            // Similar logic as Aright, for array B.
            long Bright = (cutB == n) ? 1000001L : B[cutB];

            // Check if the current partition is valid.
            // A valid partition satisfies two critical conditions:
            // 1. The largest element in the combined left partition (`Aleft` or `Bleft`) must be
            //    less than or equal to the smallest element in the combined right partition (`Bright` or `Aright`).
            //    Specifically, `Aleft <= Bright` ensures elements from A's left don't spill into B's right incorrectly.
            // 2. `Bleft <= Aright` ensures elements from B's left don't spill into A's right incorrectly.
            // If these conditions hold, we have successfully divided the two arrays into two halves
            // such that all elements in the 'left half' are less than or equal to all elements
            // in the 'right half'.
            if (Aleft <= Bright && Bleft <= Aright) {
                // If the partition is valid, calculate the median.
                // If the total number of elements is odd, the median is simply the largest
                // element in the combined left partition.
                if (totalLength % 2 == 1) {
                    return (double) Math.max(Aleft, Bleft);
                } else {
                    // If the total number of elements is even, the median is the average of
                    // the largest element in the combined left partition (max(Aleft, Bleft))
                    // and the smallest element in the combined right partition (min(Aright, Bright)).
                    // We divide by 2.0 to ensure floating-point division.
                    return (Math.max(Aleft, Bleft)
                            + Math.min(Aright, Bright)) / 2.0;
                }
            } else if (Aleft > Bright) {
                // If `Aleft` is greater than `Bright`, it means that elements in A's left partition
                // are too large, crossing into B's right partition incorrectly. This implies
                // that `cutA` is too far to the right. To correct this, we need to move `cutA`
                // further to the left. So, we adjust the binary search by setting `high` to `cutA - 1`.
                high = cutA - 1;
            } else {
                // If `Bleft` is greater than `Aright` (which is the only remaining case), it means
                // that elements in B's left partition are too large, crossing into A's right partition.
                // This implies that `cutA` is too far to the left. To correct this, we need to move `cutA`
                // further to the right. So, we adjust the binary search by setting `low` to `cutA + 1`.
                low = cutA + 1;
            }
        }

        // This line should theoretically not be reached if the input constraints are as expected
        // (sorted arrays, non-empty, etc.) and the algorithm logic is sound. It serves as a
        // fallback return or to satisfy the compiler return type requirement.
        return 0.0;
    }
