function minInterval(intervals: number[][], queries: number[]): number[] {
    intervals.sort((a, b) => a[0] - b[0]);

    // Store queries with their original indices to map results back
    const indexedQueries = queries.map((q, index) => ({ q, index }));
    indexedQueries.sort((a, b) => a.q - b.q);

    const result: number[] = new Array(queries.length).fill(-1);

    // Min Heap: [intervalSize, rightEnd]
    // Prioritizes smaller intervalSize. For ties, prioritizes smaller rightEnd.
    const heap: [number, number][] = [];

    const push = (val: [number, number]) => {
        heap.push(val);
        let idx = heap.length - 1;

        while (idx > 0) {
            const parentIdx = Math.floor((idx - 1) / 2);

            // Compare current node with parent
            // If parent is smaller size OR (sizes are equal AND parent's rightEnd is smaller or equal)
            // then parent is already higher priority or equal, so heap property is maintained.
            if (heap[parentIdx][0] < heap[idx][0] ||
                (heap[parentIdx][0] === heap[idx][0] &&
                    heap[parentIdx][1] <= heap[idx][1])) {
                break;
            }

            // Parent is lower priority, swap and bubble up
            [heap[parentIdx], heap[idx]] = [heap[idx], heap[parentIdx]];
            idx = parentIdx;
        }
    };

    const pop = (): [number, number] | undefined => {
        if (heap.length === 0) return undefined;
        if (heap.length === 1) return heap.pop();

        const top = heap[0];
        heap[0] = heap.pop()!;

        let idx = 0;

        while (true) {
            let smallest = idx;
            const left = idx * 2 + 1;
            const right = idx * 2 + 2;

            // Compare with left child
            if (
                left < heap.length &&
                (heap[left][0] < heap[smallest][0] ||
                    (heap[left][0] === heap[smallest][0] &&
                        heap[left][1] < heap[smallest][1]))
            ) {
                smallest = left;
            }

            // Compare with right child
            if (
                right < heap.length &&
                (heap[right][0] < heap[smallest][0] ||
                    (heap[right][0] === heap[smallest][0] &&
                        heap[right][1] < heap[smallest][1]))
            ) {
                smallest = right;
            }

            if (smallest === idx) break; // If current is smallest, done bubbling down

            [heap[idx], heap[smallest]] = [heap[smallest], heap[idx]];
            idx = smallest;
        }

        return top;
    };

    const peek = (): [number, number] | undefined => heap.length > 0 ? heap[0] : undefined;

    let intervalIdx = 0; // Pointer for the sorted intervals array

    for (const { q, index } of indexedQueries) {
        // 1. Add all intervals whose left end is <= current query 'q'
        while (intervalIdx < intervals.length && intervals[intervalIdx][0] <= q) {
            const [l, r] = intervals[intervalIdx];
            push([r - l + 1, r]); // Push [size, rightEnd] to heap
            intervalIdx++;
        }

        // 2. Remove all intervals from heap whose right end is < current query 'q'
        // These intervals no longer cover 'q'
        while (heap.length && peek()![1] < q) {
            pop();
        }

        // 3. The top of the heap now contains the smallest valid interval for 'q'
        if (heap.length) {
            result[index] = peek()![0]; // Store its size in the result array at original query index
        } else {
            result[index] = -1; // No interval covers 'q'
        }
    }

    return result;
}

