    public int[] minInterval(int[][] intervals, int[] queries) {

        // Sort intervals by start point.
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Store {queryValue, originalIndex}
        int[][] sortedQueries = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            sortedQueries[i][0] = queries[i];
            sortedQueries[i][1] = i;
        }

        // Sort queries by value.
        Arrays.sort(sortedQueries, (a, b) -> Integer.compare(a[0], b[0]));

        int[] result = new int[queries.length];

        /*
         * Min Heap:
         * [0] = interval size
         * [1] = interval right boundary
         */
        PriorityQueue<int[]> minHeap = new PriorityQueue<>(
            (a, b) -> Integer.compare(a[0], b[0])
        );

        int intervalIdx = 0;

        for (int[] query : sortedQueries) {

            int currentQuery = query[0];
            int originalIndex = query[1];

            // Add all intervals whose start <= current query.
            while (
                intervalIdx < intervals.length &&
                intervals[intervalIdx][0] <= currentQuery
            ) {
                int left = intervals[intervalIdx][0];
                int right = intervals[intervalIdx][1];

                int size = right - left + 1;

                minHeap.offer(new int[] { size, right });
                intervalIdx++;
            }

            // Remove intervals that cannot cover current query.
            while (
                !minHeap.isEmpty() &&
                minHeap.peek()[1] < currentQuery
            ) {
                minHeap.poll();
            }

            // Smallest valid interval.
            result[originalIndex] =
                minHeap.isEmpty() ? -1 : minHeap.peek()[0];
        }

        return result;
    }
}

