public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        // 1. Sort intervals by their start points.
        // This allows us to process intervals as their start points are encountered by the sweep line.
        sort(intervals.begin(), intervals.end());

        // 2. Create pairs of (query_value, original_index) and sort them by query_value.
        // This enables processing queries in increasing order while preserving the original order
        // for the final result mapping.
        vector<pair<int, int>> sortedQueries;
        for (int j = 0; j < queries.size(); ++j) {
            sortedQueries.push_back({queries[j], j});
        }
        sort(sortedQueries.begin(), sortedQueries.end());

        // Result array, which will store answers in the original order of queries.
        vector<int> result(queries.size());

        // Min-priority queue (min-heap): stores pairs of {interval_size, right_end}.
        // It's prioritized by interval_size (smallest size at the top).
        // The 'greater<pair<int, int>>' comparator ensures it's a min-heap based on the first element.
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;

        int intervalIdx = 0; // Pointer to keep track of the next interval to consider from the sorted intervals array.

        // 3. Iterate through the sorted queries using a sweep-line approach.
        for (const auto& q_pair : sortedQueries) {
            int currentQueryVal = q_pair.first;
            int originalQueryIdx = q_pair.second;

            // Step A: Add all intervals whose left_end is less than or equal to the current query value.
            // These intervals are now "active" and could potentially contain the current query.
            while (intervalIdx < intervals.size() && intervals[intervalIdx][0] <= currentQueryVal) {
                int left = intervals[intervalIdx][0];
                int right = intervals[intervalIdx][1];
                int size = right - left + 1;
                minHeap.push({size, right});
                intervalIdx++;
            }

            // Step B: Remove intervals from the min-heap whose right_end is less than the current query value.
            // These intervals no longer cover the current query point and are irrelevant.
            while (!minHeap.empty() && minHeap.top().second < currentQueryVal) {
                minHeap.pop();
            }

            // Step C: The top of the min-heap now contains the smallest interval size
            // among all active and valid intervals that contain currentQueryVal.
            if (!minHeap.empty()) {
                result[originalQueryIdx] = minHeap.top().first;
            } else {
                // If the heap is empty, no interval contains the current query point.
                result[originalQueryIdx] = -1;
            }
        }

        return result;
    }
};

