function minMeetingRooms(intervals: number[][]): number {
    // Extract start times from intervals and sort them in ascending order.
    const start = intervals.map(i => i[0]).sort((a, b) => a - b);
    // Extract end times from intervals and sort them in ascending order.
    const end = intervals.map(i => i[1]).sort((a, b) => a - b);

    // Initialize the result (minimum meeting rooms needed) and the current count of overlapping meetings.
    let res = 0, count = 0;
    // Initialize pointers for start and end time arrays.
    let s = 0, e = 0;

    // Iterate while there are more start times to process.
    while (s < intervals.length) {
        // If the next meeting starts before the earliest ending meeting,
        if (start[s] < end[e]) {
            // Increment the start pointer to consider the next meeting.
            s++;
            // Increment the count of overlapping meetings.
            count++;
        } else {
            // Otherwise, a meeting has ended.
            // Increment the end pointer to consider the next ending meeting.
            e++;
            // Decrement the count of overlapping meetings.
            count--;
        }

        // Update the result with the maximum number of overlapping meetings seen so far.
        res = Math.max(res, count);
    }

    // Return the minimum number of meeting rooms needed.
    return res;
}

