class DetectSquares {
    private ptsCount: Map<string, number>;
    private pts: number[][];

    constructor() {
        this.ptsCount = new Map();
        this.pts = [];
    }

    add(point: number[]): void {
        const key = `${point[0]},${point[1]}`;
        this.ptsCount.set(key, (this.ptsCount.get(key) || 0) + 1);
        this.pts.push(point);
    }

    count(point: number[]): number {
        let res = 0;
        const [px, py] = point;

        for (const [x, y] of this.pts) {
            // If the point is the same as the query point, or on the same horizontal/vertical line,
            // it cannot form a square with positive area where the query point is a diagonal corner.
            // Also, for a square, the absolute difference in x-coordinates must equal the absolute difference in y-coordinates.
            // If this condition is not met, they cannot be diagonal corners of an axis-aligned square.
            if (Math.abs(py - y) !== Math.abs(px - x) || x === px || y === py) {
                continue;
            }

            // If (px, py) and (x, y) are diagonally opposite corners of a square,
            // the other two corners must be (x, py) and (px, y).
            // We need to check if these points exist in our data structure and count them.
            const count1 = this.ptsCount.get(`${x},${py}`) || 0;
            const count2 = this.ptsCount.get(`${px},${y}`) || 0;

            // Each combination of the two missing points completes one square.
            // Since duplicate points are allowed, we multiply their counts.
            res += count1 * count2;
        }

        return res;
    }
}

