    // Stores the count of each unique point. Key is "x,y", value is frequency.
    unordered_map<string, int> ptsCount;
    // Stores all individual points added, including duplicates. Used for iteration.
    vector<vector<int>> pts;

    // Helper function to create a consistent string key for a point.
    string getKey(int x, int y) {
        return to_string(x) + "," + to_string(y);
    }

public:
    DetectSquares() {
        // Constructor initializes member variables. For unordered_map and vector, 
        // this means they are created as empty containers.
    }

    void add(vector<int> point) {
        int x = point[0];
        int y = point[1];
        string key = getKey(x, y);
        // Increment the count of this point. If the point wasn't in the map, 
        // it's automatically added with a count of 1.
        ptsCount[key]++; 
        // Store the point itself. This list is iterated over in the count method.
        pts.push_back(point);
    }

    int count(vector<int> point) {
        int res = 0;
        int px = point[0];
        int py = point[1];

        // Iterate through all previously added points (p) to find a potential diagonal partner.
        // If 'point' is (px, py) and 'p' is (x, y), these two could be diagonally opposite vertices.
        for (const auto& p : pts) {
            int x = p[0];
            int y = p[1];

            // Calculate the absolute difference in x-coordinates. This will be the side length 's' 
            // if (px, py) and (x, y) are diagonally opposite corners of an axis-aligned square.
            int sideLength = abs(px - x);

            // Conditions for a valid diagonal partner:
            // 1. sideLength must not be 0: (x, y) cannot be the same point as (px, py) to form a positive area square.
            // 2. The absolute difference in y-coordinates must equal the sideLength: 
            //    This ensures that the two points form a diagonal of an axis-aligned square.
            if (sideLength == 0 || sideLength != abs(py - y)) {
                continue; // Not a valid diagonal partner. Skip to the next point.
            }

            // If (px, py) and (x, y) are diagonally opposite corners, 
            // the other two corners of the square must be (x, py) and (px, y).
            // We need to count how many times these two points have been added.
            string key1 = getKey(x, py); // Point (x, py)
            string key2 = getKey(px, y); // Point (px, y)

            // Retrieve the counts of these two points from ptsCount. 
            // If a point doesn't exist, its count is 0.
            int count1 = ptsCount.count(key1) ? ptsCount[key1] : 0;
            int count2 = ptsCount.count(key2) ? ptsCount[key2] : 0;

            // The number of ways to form squares using (px, py) and (x, y) as diagonals 
            // is the product of the counts of the other two required corner points. 
            // This correctly handles duplicate points.
            res += count1 * count2;
        }

        return res;
    }
};

def climbStairs(n: int) -> int:
    # Base case: reached exactly the top
    if n == 0:
        return 1

    # Base case: crossed the top (invalid path)
    if n < 0:
        return 0

    # Try taking 1 step and 2 steps
    return climbStairs(n - 1) + climbStairs(n - 2)

public int climbStairs(int n) {
    // one: ways to reach the previous step
    // two: ways to reach two steps before
    int one = 1;
    int two = 1;

    // Loop n - 1 times
    for (int i = 0; i < n - 1; i++) {
        int temp = one;      // Store current value
        one = one + two;     // Sum of previous two
        two = temp;          // Shift forward
    }

    return one;
}

