function cloneGraph(node: Node | null): Node | null {
  if (!node) {
    return null;
  }

  const oldToNew = new Map<Node, Node>();
  const queue: Node[] = [node];
  oldToNew.set(node, new Node(node.val));

  while (queue.length > 0) {
    const curr = queue.shift()!;
    const clonedCurr = oldToNew.get(curr)!;

    for (const neighbor of curr.neighbors) {
      if (!oldToNew.has(neighbor)) {
        oldToNew.set(neighbor, new Node(neighbor.val));
        queue.push(neighbor);
      }
      clonedCurr.neighbors.push(oldToNew.get(neighbor)!);
    }
  }

  return oldToNew.get(node)!;
}

from collections import deque

def cloneGraph(node: 'Node') -> 'Node':
    if not node:
        return None

    oldToNew = {}
    queue = deque([node])
    oldToNew[node] = Node(node.val)

    while queue:
        curr = queue.popleft()
        clonedCurr = oldToNew[curr]

        for neighbor in curr.neighbors:
            if neighbor not in oldToNew:
                oldToNew[neighbor] = Node(neighbor.val)
                queue.append(neighbor)
            clonedCurr.neighbors.append(oldToNew[neighbor])

    return oldToNew[node]

