    // Map to store the mapping between original nodes and their cloned copies
    private Map<Node, Node> oldToNew = new HashMap<>();

    public Node cloneGraph(Node node) {

        // If the input node is null, return null
        if (node == null) return null;

        // Start DFS cloning
        return dfs(node);
    }

    private Node dfs(Node node) {

        // If this node has already been cloned, return the existing clone
        if (oldToNew.containsKey(node)) {
            return oldToNew.get(node);
        }

        // Create a clone of the current node
        Node copy = new Node(node.val);

        // Store the mapping before cloning neighbors
        // This prevents infinite recursion in cyclic graphs
        oldToNew.put(node, copy);

        // Recursively clone all neighbors
        for (Node nei : node.neighbors) {
            copy.neighbors.add(dfs(nei));
        }

        // Return the cloned node
        return copy;
    }
}

