public Node cloneGraph(Node node) {
    if (node == null) {
        return null; // Handle null input.
    }

    Queue<Node> queue = new LinkedList<>(); // Queue for BFS traversal.
    queue.offer(node); // Add the starting node to the queue.

    HashMap<Node, Node> visited = new HashMap<>(); // Map to store visited nodes and their clones.
    visited.put(node, new Node(node.val)); // Create the clone of the first node and put it in the map.

    while (!queue.isEmpty()) {
        Node curr = queue.poll(); // Get the current node from the queue.
        Node clonedCurr = visited.get(curr); // Get the clone of the current node.

        // Iterate through the neighbors of the current node.
        for (Node neighbor : curr.neighbors) {
            if (!visited.containsKey(neighbor)) {
                visited.put(neighbor, new Node(neighbor.val)); // Clone the neighbor and add it to the map.
                queue.offer(neighbor); // Add the neighbor to the queue for traversal.
            }
            clonedCurr.neighbors.add(visited.get(neighbor)); // Add the cloned neighbor to the cloned current node's neighbors.
        }
    }

    return visited.get(node); // Return the clone of the original node.
}

