#include <queue>
#include <unordered_map>

Node* cloneGraph(Node* node) {
    if (!node) {
        return nullptr; // Handle null input.
    }

    std::queue<Node*> queue; // Queue for BFS traversal.
    queue.push(node); // Add the starting node to the queue.

    std::unordered_map<Node*, Node*> visited; // Map to store visited nodes and their clones.
    visited[node] = new Node(node->val); // Create the clone of the first node and put it in the map.

    while (!queue.empty()) {
        Node* curr = queue.front(); // Get the current node from the queue.
        queue.pop(); // Remove the current node from the queue.
        Node* clonedCurr = visited[curr]; // Get the clone of the current node.

        // Iterate through the neighbors of the current node.
        for (Node* neighbor : curr->neighbors) {
            if (!visited.count(neighbor)) {
                visited[neighbor] = new Node(neighbor->val); // Clone the neighbor and add it to the map.
                queue.push(neighbor); // Add the neighbor to the queue for traversal.
            }
            clonedCurr->neighbors.push_back(visited[neighbor]); // Add the cloned neighbor to the cloned current node's neighbors.
        }
    }

    return visited[node]; // Return the clone of the original node.
}

