function lowestCommonAncestor(
  root: TreeNode | null,
  p: TreeNode,
  q: TreeNode
): TreeNode | null {

  // Start traversing from the root of the BST
  let cur = root

  // Continue traversal until we reach a null node
  while (cur) {

    // If both p and q values are greater than the current node value
    // then both nodes must lie in the right subtree
    if (p.val > cur.val && q.val > cur.val) {
      cur = cur.right
    }

    // If both p and q values are smaller than the current node value
    // then both nodes must lie in the left subtree
    else if (p.val < cur.val && q.val < cur.val) {
      cur = cur.left
    }

    // Otherwise, current node splits p and q
    // meaning one node is on the left and the other is on the right
    // OR current node itself is p or q
    // therefore this node is the Lowest Common Ancestor (LCA)
    else {
      return cur
    }
  }

  // If traversal finishes without finding LCA (edge case)
  return null
}

