public static class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {

        // Start traversal from the root node
        TreeNode cur = root;

        // Continue traversing until we reach a null node.  This ensures we cover all possible paths.
        while (cur != null) {

            // If both p and q values are greater than the current node value,
            // both nodes must be present in the right subtree. Therefore, move to the right subtree.
            if (p.val > cur.val && q.val > cur.val) {
                cur = cur.right;
            }

            // If both p and q values are smaller than the current node value,
            // both nodes must be present in the left subtree. Therefore, move to the left subtree.
            else if (p.val < cur.val && q.val < cur.val) {
                cur = cur.left;
            }

            // Otherwise, we have found the split point.
            // This means one node lies on the left subtree and the other on the right subtree,
            // or the current node itself is either p or q.  In any of these cases, the current node is the LCA.
            else {
                return cur;
            }
        }

        // Edge case: if no ancestor is found. This should not happen in a typical BST LCA problem,
        // but it's good to include for robustness.
        return null;
    }
}

