public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {

        // Start traversal from the root node
        TreeNode* cur = root;

        // Continue traversal until the current node becomes null
        while (cur) {

            // If both p and q values are greater than current node value
            // then the LCA must be in the right subtree.
            if (p->val > cur->val && q->val > cur->val) {
                cur = cur->right; // Move to the right subtree
            }

            // If both p and q values are smaller than current node value
            // then the LCA must be in the left subtree.
            else if (p->val < cur->val && q->val < cur->val) {
                cur = cur->left; // Move to the left subtree
            }

            // Otherwise, the current node is the Lowest Common Ancestor.
            // This happens when the current node's value is between p and q.
            else {
                         return cur; // Current node is the LCA
            }
        }

        // Edge case: If no common ancestor is found (should not happen in a valid BST with p and q present)
        return NULL; // Return NULL if no LCA is found (error case)
    }
