function validTree(n: number, edges: number[][]): boolean {
  // If the number of nodes is 0, it's a valid tree (vacuously true).
  if (!n) return true;

  // Create an adjacency list to represent the graph.
  const adj: Map<number, number[]> = new Map();

  // Initialize the adjacency list: each node maps to an empty array of neighbors.
  for (let i = 0; i < n; i++) {
    adj.set(i, []);
  }

  // Build the graph by adding edges to the adjacency list.
  for (const [n1, n2] of edges) {
    // For undirected graph, add n2 as neighbor of n1 and vice versa.
    adj.get(n1)!.push(n2);
    adj.get(n2)!.push(n1);
  }

  // Keep track of visited nodes during DFS to detect cycles.
  const visit = new Set<number>();

  // Depth-First Search function to detect cycles and check connectivity.
  function dfs(node: number, prev: number): boolean {
    // If the node is already visited, a cycle is detected.
    if (visit.has(node)) return false;

    // Mark the current node as visited.
    visit.add(node);

    // Iterate through the neighbors of the current node.
    for (const neighbor of adj.get(node)!) {
      // Ignore the parent node to avoid immediate backtracking.
      if (neighbor === prev) continue;

