class Heap {
  private data: number[] = [];
  private comparator: (a: number, b: number) => boolean;

  constructor(comparator: (a: number, b: number) => boolean) {
    this.comparator = comparator;
  }

  size(): number {
    return this.data.length;
  }

  peek(): number {
    return this.data[0];
  }

  push(val: number): void {
    this.data.push(val);
    this.heapifyUp();
  }

  pop(): number {
    const top = this.data[0];
    const last = this.data.pop()!;
    if (this.data.length > 0) {
      this.data[0] = last;
      this.heapifyDown();
    }
    return top;
  }

  private heapifyUp(): void {
    let i = this.data.length - 1; // Start from the last element
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2); // Calculate the parent index
      if (this.comparator(this.data[i], this.data[parent])) { // Compare with parent using the comparator
        [this.data[i], this.data[parent]] = [this.data[parent], this.data[i]]; // Swap if the current element is smaller/larger (based on comparator) than its parent
        i = parent; // Move up to the parent
      } else break; // Stop if the heap property is satisfied
    }
  }

  private heapifyDown(): void {
    let i = 0; // Start from the root
    const n = this.data.length;

    while (true) {
      let left = 2 * i + 1; // Calculate the left child index
      let right = 2 * i + 2; // Calculate the right child index
      let best = i; // Assume the current node is the smallest/largest (based on comparator)

      if (left < n && this.comparator(this.data[left], this.data[best])) { // Check if the left child exists and is smaller/larger than the current best
        best = left; // Update best to the left child
      }
      if (right < n && this.comparator(this.data[right], this.data[best])) { // Check if the right child exists and is smaller/larger than the current best
        best = right; // Update best to the right child
      }

      if (best !== i) { // If the best is not the current node, swap them
        [this.data[i], this.data[best]] = [this.data[best], this.data[i]]; // Swap the current node with the best child
        i = best; // Move down to the best child
      } else break; // Stop if the heap property is satisfied
    }
  }
}

class MedianFinder {
  private small: Heap; // max heap
  private large: Heap; // min heap

  constructor() {
    // max heap → bigger element comes first
    this.small = new Heap((a, b) => a > b);

    // min heap → smaller element comes first
    this.large = new Heap((a, b) => a < b);
