function kthSmallest(root: TreeNode | null, k: number): number {
    // Initialize a counter to keep track of visited nodes
    let n = 0
    // Initialize a stack to simulate in-order traversal
    const stack: TreeNode[] = []
    // Initialize the current node to the root
    let cur: TreeNode | null = root

    // Iterate until the current node is null and the stack is empty
    while (cur !== null || stack.length > 0) {

        // Traverse to the leftmost node of the current subtree
        while (cur !== null) {
            // Push the current node onto the stack
            stack.push(cur)
            // Move to the left child
            cur = cur.left
        }

        // Pop the top node from the stack (smallest element in the current subtree)
        cur = stack.pop()!
        // Increment the counter
        n++

        // If the counter equals k, we have found the kth smallest element
        if (n === k) {
            // Return the value of the current node
            return cur.val
        }

        // Move to the right child to explore larger elements
        cur = cur.right
    }

    // If the kth smallest element is not found, return -1 (should not happen in a valid BST)
    return -1
}

