  while (fast !== null && fast.next !== null) {

    // Move slow pointer by 1 step
    slow = slow!.next;

    // Move fast pointer by 2 steps
    fast = fast.next.next;

    // If at any point slow and fast meet,
    // there must be a cycle
    if (slow === fast) {
      return true;
    }
  }

  // If we exit the loop,
  // fast reached null → no cycle
  return false;
}

