function findOrder(
    numCourses: number,
    prerequisites: number[][]
): number[] {
    // Build the adjacency list where prereq[course] stores courses that must be taken BEFORE 'course'.
    // This effectively represents dependencies: if [A, B] means B must be taken before A, then prereq[A] contains B.
    const adj: number[][] = Array.from({ length: numCourses }, () => []);

    for (const [course, pre] of prerequisites) {
        adj[course].push(pre);
    }

    const output: number[] = []; // Stores the resulting topological order.
    const visit = new Set<number>(); // Stores courses that have been fully processed and added to output.
    const cycle = new Set<number>(); // Stores courses currently in the recursion stack (for cycle detection).

    // DFS function to explore dependencies and detect cycles.
    // Returns true if no cycle is detected in the current path, false otherwise.
    const dfs = (course: number): boolean => {
        if (cycle.has(course)) {
            return false; // Cycle detected: this course is already in the current recursion path.
        }

        if (visit.has(course)) {
            return true; // Already processed and added to output; no need to re-process.
        }

        // Mark the current course as being visited (in the recursion stack).
        cycle.add(course);

        // Recursively visit all prerequisites for the current course.
        for (const pre of adj[course]) {
            if (!dfs(pre)) {
                return false; // If a cycle is detected in any prerequisite path, propagate failure.
            }
        }

        // After visiting all prerequisites, remove the course from the cycle set
        // (it's no longer in the current recursion path, as its dependencies are handled).
        cycle.delete(course);
        // Mark the course as fully processed and add it to the output.
        visit.add(course);
        output.push(course);

        return true; // Successfully processed the course and its dependencies.
    };

    // Iterate through all courses to ensure every component of the graph is visited.
