    private boolean dfs(int course) {
        // If currently visiting (in the recursion stack), a cycle is detected.
        if (visitStatus[course] == 1) {
            return false;
        }

        // If already fully visited, no need to process again.
        if (visitStatus[course] == 2) {
            return true;
        }

        // Mark as visiting
        visitStatus[course] = 1;

        // Recursively visit all prerequisites
        for (int pre : adj.get(course)) {
            if (!dfs(pre)) {
                return false; // Cycle detected in a prerequisite path
            }
        }

        // After all prerequisites are visited and processed, mark current course as fully visited
        visitStatus[course] = 2;
        // Add course to the result list.
        // Since we add a course *after* its prerequisites, the order will be correct.
        result.add(course);

        return true;
    }
