        // Build adjacency list (graph where edge u -> v means u is a prerequisite for v)
        // In this problem, prerequisites[i] = [ai, bi] indicates that to take course ai,
        // you must first take course bi. So, there's a directed edge from bi to ai.
        vector<vector<int>> adj(numCourses);
        // Build in-degree array (count of prerequisites for each course)
        vector<int> inDegree(numCourses, 0);

        for (const auto& pre : prerequisites) {
            int course = pre[0];         // ai
            int prerequisite = pre[1];   // bi
            adj[prerequisite].push_back(course); // Add edge bi -> ai
            inDegree[course]++;          // Increment in-degree for course ai
        }

        queue<int> q;
        // Add all courses with 0 in-degree to the queue. These are courses with no prerequisites.
        for (int i = 0; i < numCourses; ++i) {
            if (inDegree[i] == 0) {
                q.push(i);
            }
        }

        vector<int> order;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            order.push_back(u);

            // For each course 'v' that has 'u' as a prerequisite (i.e., an edge u -> v exists)
            for (int v : adj[u]) {
                inDegree[v]--; // Decrement in-degree of 'v' since 'u' has now been taken
                if (inDegree[v] == 0) {
                    q.push(v); // If 'v' now has no prerequisites, add it to the queue
                }
            }
        }

        // If the number of courses in the topological order matches numCourses,
        // a valid order was found. Otherwise, a cycle exists in the graph.
        if (order.size() == numCourses) {
            return order;
        } else {
            return {}; // Return empty array if a cycle is detected
        }
