function isBalanced(root: TreeNode | null): boolean {
    // A helper DFS function that returns a tuple: [is_balanced: boolean, height: number]
    function dfs(node: TreeNode | null): [boolean, number] {
        // Base case: An empty tree is balanced and has a height of 0.
        if (!node) {
            return [true, 0];
        }

        // Recursively get balance status and height for left and right children.
        const [leftBalanced, leftHeight] = dfs(node.left);
        const [rightBalanced, rightHeight] = dfs(node.right);

        // Determine if the current subtree is balanced.
        // It's balanced if: 
        // 1. Both left and right subtrees are balanced.
        // 2. The absolute difference between their heights is at most 1.
        const balanced = leftBalanced && rightBalanced && Math.abs(leftHeight - rightHeight) <= 1;

        // Calculate the height of the current subtree.
        // Height is 1 (for the current node) plus the maximum height of its children.
        const height = 1 + Math.max(leftHeight, rightHeight);

        // Return the balance status and height for the current subtree.
        return [balanced, height];
    }

    // Start the DFS from the root and return only the balance status (the first element of the tuple).
    return dfs(root)[0];
}

