// Linear DP using array
private int robLinear(int[] nums, int start, int end) {
    int n = end - start + 1;
    int[] dp = new int[n];

    // Base cases
    dp[0] = nums[start];
    if (n > 1) {
        dp[1] = Math.max(nums[start], nums[start + 1]);
    }

    // Build DP array
    for (int i = 2; i < n; i++) {
        dp[i] = Math.max(
            dp[i - 1],                 // skip current house
            dp[i - 2] + nums[start + i] // rob current house
        );
    }

    return dp[n - 1];
}

  // Top-down DP helper with memoization
private  int dfs(int index, int end, int[] nums, Map<Integer, Integer> memo) {
    // Base case
    if (index > end) {
        return 0;
    }

    // Return cached result
    if (memo.containsKey(index)) {
        return memo.get(index);
    }

    // Option 1: rob current house
    int robCurrent = nums[index] + dfs(index + 2, end, nums, memo);

    // Option 2: skip current house
    int skipCurrent = dfs(index + 1, end, nums, memo);

    int result = Math.max(robCurrent, skipCurrent);
    memo.put(index, result);

    return result;
}
