function canPartition(nums: number[]): boolean {
    const total = nums.reduce((sum, num) => sum + num, 0);

    // If the total sum is odd, it's impossible to partition into two equal subsets.
    if (total % 2 !== 0) {
        return false;
    }

    const target = total / 2;
    // dp[s] will be true if a subset of nums can sum up to 's'.
    // We need target + 1 size because sums range from 0 to target.
    const dp: boolean[] = new Array(target + 1).fill(false);
    dp[0] = true; // A sum of 0 can always be formed (by picking no elements).

    // Iterate through each number in the input array.
    for (const num of nums) {
        // For each number, iterate backwards from target down to num.
        // Iterating backwards ensures that each number is considered only once for forming a sum
        // within a single pass, preventing reuse of the current 'num' within the same iteration.
        for (let s = target; s >= num; s--) {
            // If sum 's' can be formed (dp[s] is true) OR
            // if (s - num) could be formed (dp[s - num] is true) and we add the current 'num',
            // then 's' can be formed.
            dp[s] = dp[s] || dp[s - num];
        }
    }

    // After processing all numbers, check if the target sum can be formed.
    return dp[target];
}

