public static class Solution {
    public boolean canPartition(int[] nums) {
        // Step 1: Calculate the total sum of all elements in the input array.
        // This is a prerequisite to determine if an equal partition is even possible.
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        // Step 2: Check if the total sum is odd.
        // If the total sum is odd, it's impossible to partition it into two subsets
        // with equal integer sums (e.g., 5 / 2 = 2.5, which can't be achieved with integers).
        if (totalSum % 2 != 0) {
            return false;
        }

        // Step 3: Define the target sum for each subset.
        // If an equal partition is possible, each subset must sum up to exactly half of the total sum.
        int target = totalSum / 2;

        // Step 4: Initialize a set to store all possible sums that can be formed using
        // the numbers processed so far. A Set is used to efficiently handle unique sums
        // and provides O(1) average time complexity for add/contains operations.
        Set<Integer> reachableSums = new HashSet<>();
        // Initially, a sum of 0 is always reachable (by choosing an empty subset).
        reachableSums.add(0); 

        // Step 5: Iterate through each number in the input array 'nums'.
        // For each number, we explore new sums that can be formed by including or excluding it.
        for (int num : nums) {
            // Step 6: Create a temporary set to store the new sums that become reachable
            // after considering the current 'num'. This is crucial for two reasons:
            // 1. Avoids concurrent modification exceptions if we were to modify 'reachableSums'
            //    while iterating over it.
            // 2. Ensures that 'num' is processed based on sums reachable *before* 'num'
            //    was considered, preventing 'num' from being used multiple times within
            //    the same iteration (effectively, each number is used at most once per subset).
            Set<Integer> newReachableSums = new HashSet<>();

            // Step 7: For each sum that was previously reachable, consider two options:
            // (a) Don't include the current 'num'
            // (b) Include the current 'num'
            for (int currentSum : reachableSums) {
                // Option (a): Don't include 'num' in the subset.
                // The 'currentSum' remains reachable with the previous numbers.
                newReachableSums.add(currentSum);

                // Option (b): Include 'num' in the subset.
                // The sum 'currentSum + num' becomes a new potential reachable sum.
                int sumIncludingNum = currentSum + num;

                // Step 8: Check for early termination.
                // If we found a sum exactly equal to our 'target', we've successfully
                // partitioned the array. No need to check further.
                if (sumIncludingNum == target) {
                    return true;
                }

                // Step 9: Add the new sum if it's less than the target.
                // We only care about sums that are less than or equal to the target.
                // Sums greater than the target are not useful for reaching the exact target,
                // and we want to avoid unnecessary storage and computation.
                if (sumIncludingNum < target) {
                    newReachableSums.add(sumIncludingNum);
                }
            }
            // Step 10: Update 'reachableSums' for the next iteration.
            // The sums found in 'newReachableSums' become the basis for the next 'num'.
            reachableSums = newReachableSums;
        }

        // Step 11: After processing all numbers, check if the 'target' sum
        // is present in the final set of 'reachableSums'.
        // If it is, it means a subset summing to 'target' can be formed.
        return reachableSums.contains(target);
    }
}

