function countComponents(n: number, edges: number[][]): number {
    // Initialize parent array where par[i] = i, meaning each node is its own parent initially.
    const par: number[] = Array.from({ length: n }, (_, i) => i);
    // Initialize rank array to keep track of the size of each component.
    const rank: number[] = new Array(n).fill(1);

    // Find the root/representative of a node using path compression.
    const find = (n1: number): number => {
        let res = n1;

        // Traverse upwards until we find the root (parent[res] === res).
        while (res !== par[res]) {
            // Path compression: Make each visited node point directly to the root.
            par[res] = par[par[res]];
            res = par[res];
        }

        return res;
    };

    // Union operation: Connects two components based on rank.
    const union = (n1: number, n2: number): number => {
        // Find the root of each node.
        const p1 = find(n1);
        const p2 = find(n2);

        // If the nodes are already in the same component, return 0 (no change).
        if (p1 === p2) return 0;

        // Attach the smaller rank tree under the root of the larger rank tree.
        if (rank[p2] > rank[p1]) {
            par[p1] = p2;
            rank[p2] += rank[p1];
        } else {
            par[p2] = p1;
            rank[p1] += rank[p2];
        }

        // Successfully merged two components, return 1.
        return 1;
    };

    // Initially, the number of components equals the number of nodes.
    let res = n;

    // Iterate through the edges and perform union operations.
    for (const [n1, n2] of edges) {
        // Each successful union reduces the number of components by 1.
        res -= union(n1, n2);
    }

    // Return the final number of connected components.
    return res;
}

