public:
    int countComponents(int n, vector<vector<int>>& edges) {
        // Initialize parent and rank vectors for the Disjoint Set Union (DSU) data structure.
        vector<int> par(n);
        vector<int> rank(n);

        // Initially, each node is its own parent, and the rank is 1.
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 1;
        }

        // Initially, the number of connected components is the number of nodes.
        int res = n;

        // Iterate through each edge in the graph.
        for (auto& edge : edges) {
            int n1 = edge[0]; // Node 1.
            int n2 = edge[1]; // Node 2.
            res -= unite(n1, n2, par, rank); // Unite the sets containing n1 and n2 and decrement the component count if they were previously disjoint.
        }

        // Return the final number of connected components.
        return res;
    }

private:
    // Find the root/representative of the set to which n1 belongs using path compression.
    int find(int n1, vector<int>& par) {

        int res = n1;

        // Traverse to find the root of the set.
        while (res != par[res]) {
            // Path compression: update the parent of the current node to be the grandparent.
            par[res] = par[par[res]];
            res = par[res];
        }

        return res;
    }

    // Unite the sets containing n1 and n2 using union by rank.
    int unite(int n1, int n2, vector<int>& par, vector<int>& rank) {
        // Find the roots/representatives of the sets containing n1 and n2.
        int p1 = find(n1, par);
        int p2 = find(n2, par);

        // If n1 and n2 are already in the same set, no union is needed.
        if (p1 == p2) return 0;

        // Union by rank: attach the smaller rank tree under the root of the larger rank tree.
        if (rank[p2] > rank[p1]) {
            par[p1] = p2; // Attach p1's tree to p2's tree.
            rank[p2] += rank[p1]; // Update the rank of p2's tree.
        } else {
            par[p2] = p1; // Attach p2's tree to p1's tree.
            rank[p1] += rank[p2]; // Update the rank of p1's tree.
        }

        return 1; // Return 1 to indicate that a union operation occurred.
    }
