function minCostClimbingStairs(cost: number[]): number {
    // Add a virtual step with cost 0 at the end. This represents the "top of the floor".
    // After paying the cost of the last actual step, you effectively jump to this virtual step.
    cost.push(0);

    // Iterate backward from the third-to-last step to the first step.
    // `cost.length` now includes the virtual step. So `cost.length - 1` is the virtual top (cost 0).
    // `cost.length - 2` is the actual last step.
    // We start from `cost.length - 3` because the base cases for reaching the top
    // from `cost.length - 1` (the virtual top) and `cost.length - 2` (the last actual step)
    // are handled by their inherent values or by the virtual top's cost.
    // Specifically, `cost[cost.length - 2]` (the original last step's cost) is already the cost
    // if you jump one step to the virtual top (as `cost[cost.length - 1]` is 0).
    for (let i = cost.length - 3; i >= 0; i--) {
        // Update `cost[i]` to store the minimum cost to reach the top *starting from step i*.
        // To do this, we pay the original `cost[i]`
        // and then choose the minimum cost path from either `i+1` or `i+2` to the top.
        // Since we are iterating backward, `cost[i+1]` and `cost[i+2]` already hold
        // their respective minimum costs to the top.
        cost[i] += Math.min(cost[i + 1], cost[i + 2]);
    }

    // According to the problem, you can start from either step 0 or step 1.
    // After the loop, `cost[0]` contains the minimum cost to reach the top starting from index 0,
    // and `cost[1]` contains the minimum cost to reach the top starting from index 1.
    // We return the minimum of these two starting options.
    return Math.min(cost[0], cost[1]);
}

