public static class Solution {
    // Optimized Approach: Dynamic Programming with O(1) space
    public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;

        // minCostOneStepAway: Represents the minimum cost to reach the top
        // from the step (i+1) relative to the current step i. (conceptually dp[i+1])
        // Initially, it's dp[n], which is 0 (cost from top to top).
        int minCostOneStepAway = 0; 

        // minCostTwoStepsAway: Represents the minimum cost to reach the top
        // from the step (i+2) relative to the current step i. (conceptually dp[i+2])
        // Initially, it's dp[n+1], which is also 0 (conceptual step beyond top).
        int minCostTwoStepsAway = 0;

        // Iterate backwards through the actual steps of the staircase.
        // We start from the last actual step (index n-1) down to the first step (index 0).
        // This loop calculates the minimum cost to reach the top *starting from* step i.
        for (int i = n - 1; i >= 0; i--) {
            // The current minimum cost to reach the top from step 'i' is calculated as:
            // cost[i] (the cost to climb step i) + 
            // Math.min(minCostOneStepAway, minCostTwoStepsAway) 
            // (the minimum cost to reach the top from either taking 1 step or 2 steps from 'i').
            int currentMinCostToTop = cost[i] + Math.min(minCostOneStepAway, minCostTwoStepsAway);

            // Update the tracking variables for the next iteration (when 'i' decreases).
            // When we move to the previous step (i-1):
            // The old 'minCostOneStepAway' (which was dp[i+1]) becomes the new 'minCostTwoStepsAway' (dp[i+1] for (i-1)).
            minCostTwoStepsAway = minCostOneStepAway;
            // The 'currentMinCostToTop' (which is dp[i]) becomes the new 'minCostOneStepAway' (dp[i] for (i-1)).
            minCostOneStepAway = currentMinCostToTop;
        }

        // After the loop completes:
        // 'minCostOneStepAway' will hold the minimum cost to reach the top starting from index 0 (effectively dp[0]).
        // 'minCostTwoStepsAway' will hold the minimum cost to reach the top starting from index 1 (effectively dp[1]).
        // Since we can start from either step 0 or step 1, we return the minimum of these two values.
        return Math.min(minCostOneStepAway, minCostTwoStepsAway);
    }
}

