        // So we start from index n-2 (which is cost.size() - 3 after push_back).
        // The loop calculates the minimum cost to reach the top *starting from* step 'i'.
        for (int i = cost.size() - 3; i >= 0; --i) {
            // The cost from step 'i' is cost[i] plus the minimum of
