function ladderLength(
    beginWord: string,
    endWord: string,
    wordList: string[]
): number {
    // Edge case: If the endWord is not in the wordList, it's impossible to reach it.
    // Return 0 immediately as no ladder can be formed.
    if (!wordList.includes(endWord)) {
        return 0;
    }

    // This map will store 'patterns' (e.g., "h*t") as keys and an array of words
    // that match that pattern (e.g., ["hot", "hat"]) as values. This effectively
    // creates an 'adjacency list' for words that differ by one character.
    const neighbors = new Map<string, string[]>();

    // Include beginWord in the list of words for graph construction.
    // This ensures that if beginWord itself is not in wordList, its connections
    // can still be explored. This also avoids issues if beginWord === endWord
    // and endWord is in wordList, but beginWord is not.
    const words = [...wordList, beginWord];

    // Preprocessing step: Build the generalized graph using patterns.
    // Iterate through each word that could be part of the ladder.
    for (const word of words) {
        // For each word, generate all possible one-character-wildcard patterns.
        // Example: for "hot", patterns are "*ot", "h*t", "ho*".
        for (let j = 0; j < word.length; j++) {
            // Construct the pattern by replacing the character at index 'j' with an asterisk.
            const pattern =
                word.slice(0, j) + "*" + word.slice(j + 1);

            // If the pattern is not yet in our map, initialize an empty array for it.
            if (!neighbors.has(pattern)) {
                neighbors.set(pattern, []);
            }

            // Add the current word to the list of words associated with this pattern.
            // All words sharing the same pattern are considered neighbors in the graph.
            neighbors.get(pattern)!.push(word);
        }
    }

    // Initialize BFS components:
    // 1. A Set to keep track of visited words to prevent cycles and redundant processing.
    //    beginWord is the starting point, so it's marked as visited initially.
    const visited = new Set<string>([beginWord]);

    // 2. A queue for BFS, initialized with the beginWord.
    const queue: string[] = [beginWord];
    // 3. The current ladder length (level in BFS). Starts at 1 for the beginWord itself.
    let level = 1;

    // Main BFS loop: Continues as long as there are words to process in the queue.
    while (queue.length > 0) {
        // Get the number of nodes at the current level.
        // We process all nodes at the current level before moving to the next level.
        const size = queue.length;

        // Process each word at the current level.
        for (let i = 0; i < size; i++) {
            // Dequeue the current word to process.
            // The '!' asserts that queue.shift() will not return undefined (queue.length > 0).
            const word = queue.shift()!;

            // If the current word is the endWord, we have found the shortest path.
            // Return the current level (ladder length).
            if (word === endWord) {
                return level;
            }

            // Explore neighbors of the current word.
            // Generate all possible patterns for the current word.
            for (let j = 0; j < word.length; j++) {
                // Create a pattern (e.g., "hot" -> "h*t").
                const pattern =
                    word.slice(0, j) + "*" + word.slice(j + 1);

                // Retrieve all words that match this pattern from our pre-built 'neighbors' map.
                // These are all potential one-character-difference neighbors.
                // Use '|| []' to handle cases where a pattern might not have any associated words (e.g., if a pattern only has the current 'word' itself and it's already visited).
                const nextWords = neighbors.get(pattern) || [];

                // Iterate through these potential neighbors.
                for (const nextWord of nextWords) {
                    // If a neighbor has not been visited yet:
                    if (!visited.has(nextWord)) {
                        // Mark it as visited.
                        visited.add(nextWord);
                        // Enqueue it to be processed in the next level of BFS.
                        queue.push(nextWord);
                    }
                }
            }
        }

        // After processing all words at the current level, increment the level.
        // This signifies moving one step further in the word ladder.
        level++;
    }

    // If the queue becomes empty and the endWord was never reached,
    // it means no transformation sequence exists.
    return 0;
}

