public static class Solution {

    public int ladderLength(
        String beginWord,
        String endWord,
        List<String> wordList
    ) {

        // Step 1: Initial check for the target word.
        // If the endWord is not present in the provided wordList, it's impossible
        // to form a ladder ending at endWord. In this case, return 0 immediately.
        if (!wordList.contains(endWord)) {
            return 0;
        }

        // Step 2: Preprocessing to build an optimized 'graph' representation.
        // We create a map where keys are 'patterns' (words with one character replaced by '*')
        // and values are lists of words that match that pattern. This effectively groups
        // words that are one character apart, allowing for efficient neighbor lookup.
        // Example: "hot" -> "h*t", "*ot", "ho*". The map entry for "h*t" might contain ["hot", "hit", "hat"].
        Map<String, List<String>> neighbors = new HashMap<>();

        // Create a new list of words to include the beginWord. It's crucial that
        // beginWord is part of our word set for graph construction, even if it's
        // not originally in wordList, as it's our starting point.
        List<String> words = new ArrayList<>(wordList);
        words.add(beginWord);

        // Iterate through every word (including beginWord) to populate the neighbors map.
        for (String word : words) {
            // For each word, generate all possible patterns by replacing one character with '*'.
            // For a word of length L, there will be L such patterns.
            for (int i = 0; i < word.length(); i++) {
                // Construct the pattern string: concatenate substring before 'i', '*', and substring after 'i'.
                String pattern =
                    word.substring(0, i)
                    + "*"
                    + word.substring(i + 1);

                // Add the current word to the list associated with this pattern.
                // If the pattern is new, computeIfAbsent will create a new ArrayList for it.
                neighbors
                    .computeIfAbsent(pattern, k -> new ArrayList<>())
                    .add(word);
            }
        }

        // Step 3: Breadth-First Search (BFS) Initialization.
        // BFS is the ideal algorithm for finding the shortest path in an unweighted graph.

        // `visited` set to keep track of words already processed. This prevents cycles
        // and ensures each word is processed only once at its shortest path distance.
        Set<String> visited = new HashSet<>();
        visited.add(beginWord); // Mark the starting word as visited.

        // `queue` for BFS, storing words to be explored in a level-by-level manner.
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord); // Add the beginWord to start the BFS.

        // `level` counter tracks the length of the current transformation sequence.
        // It starts at 1, representing the beginWord itself as the first step.
        int level = 1;

        // Step 4: BFS Traversal Loop.
        // Continue as long as there are words in the queue to process.
        while (!queue.isEmpty()) {
            // Get the number of words currently at this level. This allows us to process
            // all words at the current depth before incrementing the level counter.
            int size = queue.size();

            // Process all words at the current level.
            for (int i = 0; i < size; i++) {
                // Dequeue the current word to process.
                String word = queue.poll();

                // If the dequeued word is the endWord, we have found the shortest path.
                // The current 'level' represents the length of this shortest transformation sequence.
                if (word.equals(endWord)) {
                    return level;
                }

                // Find all potential next words (neighbors) for the current word.
                // This is done by regenerating its patterns and querying the 'neighbors' map.
                for (int j = 0; j < word.length(); j++) {
                    // Generate a pattern for the current word by replacing the character at index 'j' with '*'.
                    String pattern =
                        word.substring(0, j)
                        + "*"
                        + word.substring(j + 1);

                    // Retrieve all words from the 'neighbors' map that match this pattern.
                    // These are all words that are exactly one character different from 'word' (and other words in the list).
                    // getOrDefault handles cases where a pattern might not exist as a key, returning an empty list.
                    for (String nextWord :
                            neighbors.getOrDefault(pattern, Collections.emptyList())) {

                        // If the nextWord has not been visited yet, it means we found a new valid word
                        // that is one step away from the current 'word' and is on a shortest path.
                        if (!visited.contains(nextWord)) {
                            visited.add(nextWord); // Mark it as visited to avoid reprocessing.
                            queue.offer(nextWord); // Add it to the queue for processing in the next level.
                        }
                    }
                }
            }

            // After processing all words at the current level, increment the level counter.
            // This signifies moving one step further in the word ladder (one more transformation).
            level++;
        }

        // If the queue becomes empty and the endWord was never reached, it means
        // no transformation sequence exists between beginWord and endWord.
        return 0;
    }
}

