class Solution {
public:
    int ladderLength(
        string beginWord,
        string endWord,
        vector<string>& wordList
    ) {
        // Step 1: Initial check for the existence of endWord in the wordList.
        // If endWord is not present, it's impossible to reach, so return 0 immediately.
        bool found = false;
        for (const auto& word : wordList) {
            if (word == endWord) {
                found = true;
                break;
            }
        }

        if (!found)
            return 0; // endWord not found in the provided dictionary.

        // Step 2: Preprocessing to build a graph of one-letter-different words.
        // Instead of building an explicit graph, we use a 'pattern' approach.
        // An unordered_map stores patterns (e.g., "hot" -> "h*t", "h*t" -> "hot", "dot", "lot")
        // where a '*' denotes a wildcard character. This allows for O(1) average time lookup
        // of all words that differ by one character from a given word.
        unordered_map<string, vector<string>> neighbors;

        // Create a consolidated list of all words, including beginWord, for pattern generation.
        // This ensures that beginWord's potential neighbors are also added to the map.
        vector<string> words = wordList;
        words.push_back(beginWord);

        // Iterate through each word in the consolidated list.
        for (const string& word : words) {
            // For each word, generate all possible one-letter-different patterns.
            // Example: for "hot", patterns are "*ot", "h*t", "ho*".
            for (int i = 0; i < word.size(); i++) {
                // Construct the pattern by replacing the character at index 'i' with a '*'.
                string pattern =
                    word.substr(0, i) + // Part of the word before the current character.
                    "*" +                 // The wildcard character.
                    word.substr(i + 1); // Part of the word after the current character.

                // Map this pattern to the current word. This means 'word' matches 'pattern'.
                // Multiple words can match the same pattern (e.g., "hot", "dot", "lot" all match "*ot").
                neighbors[pattern].push_back(word);
            }
        }

        // Step 3: Initialize Breadth-First Search (BFS).
        // BFS is used to find the shortest path in an unweighted graph.

        // 'visited' set keeps track of words already processed to prevent cycles
        // and redundant processing, ensuring we find the shortest path.
        unordered_set<string> visited;
        visited.insert(beginWord);

        // 'q' is the queue for BFS, storing words to visit.
        queue<string> q;
        q.push(beginWord);

        // 'level' represents the current length of the word ladder.
        // It starts at 1, as 'beginWord' itself counts as the first step.
        int level = 1;

        // Step 4: Perform BFS traversal.
        // The loop continues as long as there are words to explore.
        while (!q.empty()) {
            // 'size' holds the number of words at the current level.
            // Processing all words at the current level before moving to the next
            // ensures that we find the shortest path.
            int size = q.size();

            // Iterate through all words currently in the queue (at the current level).
            for (int i = 0; i < size; i++) {
                // Dequeue the current word.
                string word = q.front();
                q.pop();

                // If the current word is the endWord, we have found the shortest ladder.
                // Return the current level, which represents the length of this ladder.
                if (word == endWord)
                    return level;

                // Find all potential next words (neighbors) for the current word.
                // This involves generating patterns for the current word again.
                for (int j = 0; j < word.size(); j++) {
                    // Generate a pattern for the current word by replacing the j-th character with '*'.
                    string pattern =
                        word.substr(0, j) +
                        "*" +
                        word.substr(j + 1);

                    // Retrieve all words that match this pattern from our 'neighbors' map.
                    // These are potential next words that differ by one letter.
                    for (const string& nextWord : neighbors[pattern]) {
                        // If a neighbor has not been visited yet:
                        if (!visited.count(nextWord)) {
                            // Mark it as visited to avoid reprocessing.
                            visited.insert(nextWord);
                            // Add it to the queue for exploration in the next level.
                            q.push(nextWord);
                        }
                    }
                }
            }

            // After processing all words at the current level, increment the ladder length.
            level++;
        }

        // Step 5: If the queue becomes empty and endWord was never reached,
        // it means no transformation sequence exists.
        return 0; // No path found.
    }
