                capture(board, 0, c);
            }
            // Bottom border
            if (board[ROWS - 1][c] == 'O') {
                capture(board, ROWS - 1, c);
            }
        }

        // Iterate through the left and right borders
        for (int r = 0; r < ROWS; ++r) {
            // Left border
            if (board[r][0] == 'O') {
                capture(board, r, 0);
            }
            // Right border
            if (board[r][COLS - 1] == 'O') {
                capture(board, r, COLS - 1);
            }
        }

        // Step 2: Convert surrounded 'O's to 'X' and restore 'T's to 'O's
        for (int r = 0; r < ROWS; ++r) {
            for (int c = 0; c < COLS; ++c) {
                if (board[r][c] == 'O') {
                    // This 'O' was not reachable from any border 'O', so it's surrounded.
                    board[r][c] = 'X';
                } else if (board[r][c] == 'T') {
                    // This 'T' was an 'O' connected to a border, restore it.
                    board[r][c] = 'O';
                }
            }
        }
    }
};

