/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

interface TreeNode {
    val: number;
    left: TreeNode | null;
    right: TreeNode | null;
}

function goodNodes(root: TreeNode | null): number {
    // If the tree is empty, there are no good nodes.
    if (!root) {
        return 0;
    }

    /**
     * Helper function to perform Depth-First Search (DFS).
     * It traverses the tree, keeping track of the maximum value encountered
     * on the path from the root to the current node's parent.
     * @param node The current node being visited.
     * @param maxVal The maximum value found in the path from the root down to the current node's parent.
     * @returns The count of good nodes in the subtree rooted at 'node'.
     */
    const dfs = (node: TreeNode | null, maxVal: number): number => {
        // Base case: If the current node is null, it contributes 0 good nodes.
        if (!node) {
            return 0;
        }

        // Check if the current node is a 'good' node.
        // A node is good if its value is greater than or equal to 'maxVal'
        // (the maximum value on the path from root to its parent).
        let goodNodesCount = node.val >= maxVal ? 1 : 0;

        // Update 'maxVal' for the children. The new 'maxVal' is the maximum
        // of the current 'maxVal' and the current node's value.
        // This 'maxVal' will be passed down to the children, representing the max on their path.
        const newMaxVal = Math.max(maxVal, node.val);

        // Recursively call dfs for the left and right children
        // and add their respective good node counts to the total.
        goodNodesCount += dfs(node.left, newMaxVal);
        goodNodesCount += dfs(node.right, newMaxVal);

        return goodNodesCount;
    };

    // Start the DFS from the root. The initial maxVal for the root node's path
    // is its own value, ensuring the root is always considered a good node.
    return dfs(root, root.val);
}

